  1→import path from "node:path";
  2→import os from "node:os";
  3→import { ConfigManager } from "./config.js";
  4→import { AgentManager } from "./agent-manager.js";
  5→import { SessionManager } from "./session-manager.js";
  6→import { SessionBridge } from "./session-bridge.js";
  7→import { NotificationManager } from "./notification.js";
  8→import { ChannelAdapter } from "./channel.js";
  9→import { Session } from "./session.js";
 10→import { MessageTransformer } from "./message-transformer.js";
 11→import { JsonFileSessionStore, type SessionStore } from "./session-store.js";
 12→import type { IncomingMessage } from "./types.js";
 13→import type { TunnelService } from "../tunnel/tunnel-service.js";
 14→import { getAgentCapabilities } from "./agent-registry.js";
 15→import { AgentCatalog } from "./agent-catalog.js";
 16→import { createChildLogger } from "./log.js";
 17→const log = createChildLogger({ module: "core" });
 18→
 19→export class OpenACPCore {
 20→  configManager: ConfigManager;
 21→  agentCatalog: AgentCatalog;
 22→  agentManager: AgentManager;
 23→  sessionManager: SessionManager;
 24→  notificationManager: NotificationManager;
 25→  messageTransformer: MessageTransformer;
 26→  adapters: Map<string, ChannelAdapter> = new Map();
 27→  /** Set by main.ts — triggers graceful shutdown with restart exit code */
 28→  requestRestart: (() => Promise<void>) | null = null;
 29→  private _tunnelService?: TunnelService;
 30→  private sessionStore: SessionStore | null = null;
 31→  private resumeLocks: Map<string, Promise<Session | null>> = new Map();
 32→
 33→  constructor(configManager: ConfigManager) {
 34→    this.configManager = configManager;
 35→    const config = configManager.get();
 36→    this.agentCatalog = new AgentCatalog();
 37→    this.agentCatalog.load();
 38→    this.agentManager = new AgentManager(this.agentCatalog);
 39→    const storePath = path.join(os.homedir(), ".openacp", "sessions.json");
 40→    this.sessionStore = new JsonFileSessionStore(
 41→      storePath,
 42→      config.sessionStore.ttlDays,
 43→    );
 44→    this.sessionManager = new SessionManager(this.sessionStore);
 45→    this.notificationManager = new NotificationManager(this.adapters);
 46→    this.messageTransformer = new MessageTransformer();
 47→
 48→    // Hot-reload: handle config changes that need side effects
 49→    this.configManager.on('config:changed', async ({ path: configPath, value }: { path: string; value: unknown }) => {
 50→      if (configPath === 'logging.level' && typeof value === 'string') {
 51→        const { setLogLevel } = await import('./log.js')
 52→        setLogLevel(value)
 53→        log.info({ level: value }, 'Log level changed at runtime')
 54→      }
 55→    })
 56→  }
 57→
 58→  get tunnelService(): TunnelService | undefined {
 59→    return this._tunnelService;
 60→  }
 61→
 62→  set tunnelService(service: TunnelService | undefined) {
 63→    this._tunnelService = service;
 64→    this.messageTransformer = new MessageTransformer(service);
 65→  }
 66→
 67→  registerAdapter(name: string, adapter: ChannelAdapter): void {
 68→    this.adapters.set(name, adapter);
 69→  }
 70→
 71→  async start(): Promise<void> {
 72→    this.agentCatalog.refreshRegistryIfStale().catch((err) => {
 73→      log.warn({ err }, "Background registry refresh failed");
 74→    });
 75→    for (const adapter of this.adapters.values()) {
 76→      await adapter.start();
 77→    }
 78→  }
 79→
 80→  async stop(): Promise<void> {
 81→    // 1. Notify users
 82→    try {
 83→      await this.notificationManager.notifyAll({
 84→        sessionId: "system",
 85→        type: "error",
 86→        summary: "OpenACP is shutting down",
 87→      });
 88→    } catch {
 89→      /* best effort */
 90→    }
 91→
 92→    // 2. Destroy all sessions
 93→    await this.sessionManager.destroyAll();
 94→
 95→    // 3. Stop adapters
 96→    for (const adapter of this.adapters.values()) {
 97→      await adapter.stop();
 98→    }
 99→  }
100→
101→  // --- Message Routing ---
102→
103→  async handleMessage(message: IncomingMessage): Promise<void> {
104→    const config = this.configManager.get();
105→    log.debug(
106→      {
107→        channelId: message.channelId,
108→        threadId: message.threadId,
109→        userId: message.userId,
110→      },
111→      "Incoming message",
112→    );
113→
114→    // Security: check allowed user IDs
115→    if (config.security.allowedUserIds.length > 0) {
116→      if (!config.security.allowedUserIds.includes(message.userId)) {
117→        log.warn(
118→          { userId: message.userId },
119→          "Rejected message from unauthorized user",
120→        );
121→        return;
122→      }
123→    }
124→
125→    // Check concurrent session limit
126→    const activeSessions = this.sessionManager
127→      .listSessions()
128→      .filter((s) => s.status === "active" || s.status === "initializing");
129→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
130→      log.warn(
131→        {
132→          userId: message.userId,
133→          currentCount: activeSessions.length,
134→          max: config.security.maxConcurrentSessions,
135→        },
136→        "Session limit reached",
137→      );
138→      const adapter = this.adapters.get(message.channelId);
139→      if (adapter) {
140→        await adapter.sendMessage(message.threadId, {
141→          type: "error",
142→          text: `⚠️ Session limit reached (${config.security.maxConcurrentSessions}). Please cancel existing sessions with /cancel before starting new ones.`,
143→        });
144→      }
145→      return;
146→    }
147→
148→    // Find session by thread
149→    let session = this.sessionManager.getSessionByThread(
150→      message.channelId,
151→      message.threadId,
152→    );
153→
154→    // Lazy resume: try to restore session from store
155→    if (!session) {
156→      session = (await this.lazyResume(message)) ?? undefined;
157→    }
158→
159→    if (!session) {
160→      log.warn(
161→        { channelId: message.channelId, threadId: message.threadId },
162→        "No session found for thread (in-memory miss + lazy resume returned null)",
163→      );
164→      return;
165→    }
166→
167→    // Update activity timestamp
168→    this.sessionManager.patchRecord(session.id, { lastActiveAt: new Date().toISOString() });
169→
170→    // Forward to session
171→    await session.enqueuePrompt(message.text);
172→  }
173→
174→  // --- Unified Session Creation Pipeline ---
175→
176→  async createSession(params: {
177→    channelId: string;
178→    agentName: string;
179→    workingDirectory: string;
180→    resumeAgentSessionId?: string;
181→    existingSessionId?: string;
182→    createThread?: boolean;
183→    initialName?: string;
184→  }): Promise<Session> {
185→    // 1. Spawn or resume agent
186→    const agentInstance = params.resumeAgentSessionId
187→      ? await this.agentManager.resume(
188→          params.agentName,
189→          params.workingDirectory,
190→          params.resumeAgentSessionId,
191→        )
192→      : await this.agentManager.spawn(
193→          params.agentName,
194→          params.workingDirectory,
195→        );
196→
197→    // 2. Create Session instance
198→    const session = new Session({
199→      id: params.existingSessionId,
200→      channelId: params.channelId,
201→      agentName: params.agentName,
202→      workingDirectory: params.workingDirectory,
203→      agentInstance,
204→    });
205→    session.agentSessionId = agentInstance.sessionId;
206→    if (params.initialName) {
207→      session.name = params.initialName;
208→    }
209→
210→    // 3. Register in SessionManager
211→    this.sessionManager.registerSession(session);
212→
213→    // 4. Create thread if needed
214→    const adapter = this.adapters.get(params.channelId);
215→    if (params.createThread && adapter) {
216→      const threadId = await adapter.createSessionThread(
217→        session.id,
218→        params.initialName ?? `🔄 ${params.agentName} — New Session`,
219→      );
220→      session.threadId = threadId;
221→    }
222→
223→    // 5. Connect SessionBridge
224→    if (adapter) {
225→      const bridge = this.createBridge(session, adapter);
226→      bridge.connect();
227→    }
228→
229→    // 6. Persist initial record
230→    // Preserve existing platform data (e.g. topicId) when resuming an existing session
231→    const existingRecord = this.sessionStore?.get(session.id);
232→    const platform: Record<string, unknown> = {
233→      ...(existingRecord?.platform ?? {}),
234→    };
235→    if (session.threadId) {
236→      platform.topicId = Number(session.threadId);
237→    }
238→    await this.sessionManager.patchRecord(session.id, {
239→      sessionId: session.id,
240→      agentSessionId: agentInstance.sessionId,
241→      agentName: params.agentName,
242→      workingDir: params.workingDirectory,
243→      channelId: params.channelId,
244→      status: session.status,
245→      createdAt: session.createdAt.toISOString(),
246→      lastActiveAt: new Date().toISOString(),
247→      name: session.name,
248→      platform,
249→    });
250→
251→    log.info(
252→      { sessionId: session.id, agentName: params.agentName },
253→      "Session created via pipeline",
254→    );
255→    return session;
256→  }
257→
258→  async handleNewSession(
259→    channelId: string,
260→    agentName?: string,
261→    workspacePath?: string,
262→  ): Promise<Session> {
263→    const config = this.configManager.get();
264→    const resolvedAgent = agentName || config.defaultAgent;
265→    log.info({ channelId, agentName: resolvedAgent }, "New session request");
266→    const agentDef = this.agentCatalog.resolve(resolvedAgent);
267→    const resolvedWorkspace = this.configManager.resolveWorkspace(
268→      workspacePath || agentDef?.workingDirectory,
269→    );
270→
271→    return this.createSession({
272→      channelId,
273→      agentName: resolvedAgent,
274→      workingDirectory: resolvedWorkspace,
275→    });
276→  }
277→
278→  async adoptSession(
279→    agentName: string,
280→    agentSessionId: string,
281→    cwd: string,
282→  ): Promise<
283→    | { ok: true; sessionId: string; threadId: string; status: "adopted" | "existing" }
284→    | { ok: false; error: string; message: string }
285→  > {
286→    // 1. Validate agent supports resume
287→    const caps = getAgentCapabilities(agentName);
288→    if (!caps.supportsResume) {
289→      return { ok: false, error: "agent_not_supported", message: `Agent '${agentName}' does not support session resume` };
290→    }
291→
292→    const agentDef = this.agentManager.getAgent(agentName);
293→    if (!agentDef) {
294→      return { ok: false, error: "agent_not_supported", message: `Agent '${agentName}' not found` };
295→    }
296→
297→    // 2. Validate cwd
298→    const { existsSync } = await import("node:fs");
299→    if (!existsSync(cwd)) {
300→      return { ok: false, error: "invalid_cwd", message: `Directory does not exist: ${cwd}` };
301→    }
302→
303→    // 3. Check session limit
304→    const maxSessions = this.configManager.get().security.maxConcurrentSessions;
305→    if (this.sessionManager.listSessions().length >= maxSessions) {
306→      return { ok: false, error: "session_limit", message: "Maximum concurrent sessions reached" };
307→    }
308→
309→    // 4. Check if session already exists
310→    const existingRecord = this.sessionManager.getRecordByAgentSessionId(agentSessionId);
311→    if (existingRecord) {
312→      const platform = existingRecord.platform as { topicId?: number } | undefined;
313→      if (platform?.topicId) {
314→        const adapter = this.adapters.values().next().value;
315→        if (adapter) {
316→          try {
317→            await adapter.sendMessage(existingRecord.sessionId, {
318→              type: "text",
319→              text: "Session resumed from CLI.",
320→            });
321→          } catch { /* Topic may be deleted */ }
322→        }
323→        return {
324→          ok: true,
325→          sessionId: existingRecord.sessionId,
326→          threadId: String(platform.topicId),
327→          status: "existing",
328→        };
329→      }
330→    }
331→
332→    // 5. Find default adapter
333→    const firstEntry = this.adapters.entries().next().value;
334→    if (!firstEntry) {
335→      return { ok: false, error: "no_adapter", message: "No channel adapter registered" };
336→    }
337→    const [adapterChannelId] = firstEntry;
338→
339→    // 6. Create session via unified pipeline
340→    let session: Session;
341→    try {
342→      session = await this.createSession({
343→        channelId: adapterChannelId,
344→        agentName,
345→        workingDirectory: cwd,
346→        resumeAgentSessionId: agentSessionId,
347→        createThread: true,
348→        initialName: "Adopted session",
349→      });
350→    } catch (err) {
351→      return {
352→        ok: false,
353→        error: "resume_failed",
354→        message: `Failed to resume session: ${err instanceof Error ? err.message : String(err)}`,
355→      };
356→    }
357→
358→    // 7. Update store with adopt-specific fields
359→    await this.sessionManager.patchRecord(session.id, {
360→      originalAgentSessionId: agentSessionId,
361→      platform: { topicId: Number(session.threadId) },
362→    });
363→
364→    return {
365→      ok: true,
366→      sessionId: session.id,
367→      threadId: session.threadId,
368→      status: "adopted",
369→    };
370→  }
371→
372→  async handleNewChat(
373→    channelId: string,
374→    currentThreadId: string,
375→  ): Promise<Session | null> {
376→    const currentSession = this.sessionManager.getSessionByThread(
377→      channelId,
378→      currentThreadId,
379→    );
380→
381→    if (currentSession) {
382→      return this.handleNewSession(
383→        channelId,
384→        currentSession.agentName,
385→        currentSession.workingDirectory,
386→      );
387→    }
388→
389→    // Fallback: look up from store (e.g. after restart before lazy resume)
390→    const record = this.sessionManager.getRecordByThread(channelId, currentThreadId);
391→    if (!record || record.status === "cancelled" || record.status === "error") return null;
392→
393→    return this.handleNewSession(
394→      channelId,
395→      record.agentName,
396→      record.workingDir,
397→    );
398→  }
399→
400→  // --- Lazy Resume ---
401→
402→  private async lazyResume(message: IncomingMessage): Promise<Session | null> {
403→    const store = this.sessionStore;
404→    if (!store) return null;
405→
406→    const lockKey = `${message.channelId}:${message.threadId}`;
407→
408→    // Check for existing resume in progress
409→    const existing = this.resumeLocks.get(lockKey);
410→    if (existing) return existing;
411→
412→    const record = store.findByPlatform(
413→      message.channelId,
414→      (p) => String(p.topicId) === message.threadId,
415→    );
416→    if (!record) {
417→      log.debug(
418→        { threadId: message.threadId, channelId: message.channelId },
419→        "No session record found for thread",
420→      );
421→      return null;
422→    }
423→
424→    // Don't resume cancelled/error sessions
425→    if (record.status === "cancelled" || record.status === "error") {
426→      log.debug(
427→        { threadId: message.threadId, sessionId: record.sessionId, status: record.status },
428→        "Skipping resume of cancelled/error session",
429→      );
430→      return null;
431→    }
432→
433→    log.info(
434→      { threadId: message.threadId, sessionId: record.sessionId, status: record.status },
435→      "Lazy resume: found record, attempting resume",
436→    );
437→
438→    const resumePromise = (async (): Promise<Session | null> => {
439→      try {
440→        const session = await this.createSession({
441→          channelId: record.channelId,
442→          agentName: record.agentName,
443→          workingDirectory: record.workingDir,
444→          resumeAgentSessionId: record.agentSessionId,
445→          existingSessionId: record.sessionId,
446→          initialName: record.name,
447→        });
448→        session.threadId = message.threadId;
449→        session.activate();
450→        session.dangerousMode = record.dangerousMode ?? false;
451→
452→        log.info(
453→          { sessionId: session.id, threadId: message.threadId },
454→          "Lazy resume successful",
455→        );
456→        return session;
457→      } catch (err) {
458→        log.error({ err, record }, "Lazy resume failed");
459→        // Send error feedback to user instead of silent drop
460→        const adapter = this.adapters.get(message.channelId);
461→        if (adapter) {
462→          try {
463→            await adapter.sendMessage(message.threadId, {
464→              type: "error",
465→              text: `⚠️ Failed to resume session: ${err instanceof Error ? err.message : String(err)}`,
466→            });
467→          } catch { /* best effort */ }
468→        }
469→        return null;
470→      } finally {
471→        this.resumeLocks.delete(lockKey);
472→      }
473→    })();
474→
475→    this.resumeLocks.set(lockKey, resumePromise);
476→    return resumePromise;
477→  }
478→
479→  // --- Event Wiring ---
480→
481→  /** Create a SessionBridge for the given session and adapter */
482→  createBridge(session: Session, adapter: ChannelAdapter): SessionBridge {
483→    return new SessionBridge(session, adapter, {
484→      messageTransformer: this.messageTransformer,
485→      notificationManager: this.notificationManager,
486→      sessionManager: this.sessionManager,
487→    });
488→  }
489→
490→}
