  1→import { z } from "zod";
  2→import * as fs from "node:fs";
  3→import * as path from "node:path";
  4→import * as os from "node:os";
  5→import { EventEmitter } from "node:events";
  6→import { applyMigrations } from "./config-migrations.js";
  7→import { createChildLogger } from "./log.js";
  8→const log = createChildLogger({ module: "config" });
  9→
 10→const BaseChannelSchema = z
 11→  .object({
 12→    enabled: z.boolean().default(false),
 13→    adapter: z.string().optional(), // package name for plugin adapters
 14→  })
 15→  .passthrough();
 16→
 17→export const PLUGINS_DIR = path.join(os.homedir(), ".openacp", "plugins");
 18→
 19→const AgentSchema = z.object({
 20→  command: z.string(),
 21→  args: z.array(z.string()).default([]),
 22→  workingDirectory: z.string().optional(),
 23→  env: z.record(z.string(), z.string()).default({}),
 24→});
 25→
 26→const LoggingSchema = z
 27→  .object({
 28→    level: z
 29→      .enum(["silent", "debug", "info", "warn", "error", "fatal"])
 30→      .default("info"),
 31→    logDir: z.string().default("~/.openacp/logs"),
 32→    maxFileSize: z.union([z.string(), z.number()]).default("10m"),
 33→    maxFiles: z.number().default(7),
 34→    sessionLogRetentionDays: z.number().default(30),
 35→  })
 36→  .default({});
 37→
 38→export type LoggingConfig = z.infer<typeof LoggingSchema>;
 39→
 40→const TunnelAuthSchema = z
 41→  .object({
 42→    enabled: z.boolean().default(false),
 43→    token: z.string().optional(),
 44→  })
 45→  .default({});
 46→
 47→const TunnelSchema = z
 48→  .object({
 49→    enabled: z.boolean().default(false),
 50→    port: z.number().default(3100),
 51→    provider: z.enum(["cloudflare", "ngrok", "bore", "tailscale"]).default("cloudflare"),
 52→    options: z.record(z.string(), z.unknown()).default({}),
 53→    storeTtlMinutes: z.number().default(60),
 54→    auth: TunnelAuthSchema,
 55→  })
 56→  .default({});
 57→
 58→export type TunnelConfig = z.infer<typeof TunnelSchema>;
 59→
 60→export const ConfigSchema = z.object({
 61→  channels: z.record(z.string(), BaseChannelSchema),
 62→  agents: z.record(z.string(), AgentSchema).optional().default({}),
 63→  defaultAgent: z.string(),
 64→  workspace: z
 65→    .object({
 66→      baseDir: z.string().default("~/openacp-workspace"),
 67→    })
 68→    .default({}),
 69→  security: z
 70→    .object({
 71→      allowedUserIds: z.array(z.string()).default([]),
 72→      maxConcurrentSessions: z.number().default(20),
 73→      sessionTimeoutMinutes: z.number().default(60),
 74→    })
 75→    .default({}),
 76→  logging: LoggingSchema,
 77→  runMode: z.enum(['foreground', 'daemon']).default('foreground'),
 78→  autoStart: z.boolean().default(false),
 79→  api: z.object({
 80→    port: z.number().default(21420),
 81→    host: z.string().default('127.0.0.1'),
 82→  }).default({}),
 83→  sessionStore: z
 84→    .object({
 85→      ttlDays: z.number().default(30),
 86→    })
 87→    .default({}),
 88→  tunnel: TunnelSchema,
 89→  integrations: z.record(z.string(), z.object({
 90→    installed: z.boolean(),
 91→    installedAt: z.string().optional(),
 92→  })).default({}),
 93→});
 94→
 95→export type Config = z.infer<typeof ConfigSchema>;
 96→
 97→export function expandHome(p: string): string {
 98→  if (p.startsWith("~")) {
 99→    return path.join(os.homedir(), p.slice(1));
100→  }
101→  return p;
102→}
103→
104→const DEFAULT_CONFIG = {
105→  channels: {
106→    telegram: {
107→      enabled: false,
108→      botToken: "YOUR_BOT_TOKEN_HERE",
109→      chatId: 0,
110→      notificationTopicId: null,
111→      assistantTopicId: null,
112→    },
113→  },
114→  agents: {
115→    claude: { command: "claude-agent-acp", args: [], env: {} },
116→    codex: { command: "codex", args: ["--acp"], env: {} },
117→  },
118→  defaultAgent: "claude",
119→  workspace: { baseDir: "~/openacp-workspace" },
120→  security: {
121→    allowedUserIds: [],
122→    maxConcurrentSessions: 20,
123→    sessionTimeoutMinutes: 60,
124→  },
125→  sessionStore: { ttlDays: 30 },
126→  tunnel: {
127→    enabled: true,
128→    port: 3100,
129→    provider: "cloudflare",
130→    options: {},
131→    storeTtlMinutes: 60,
132→    auth: { enabled: false },
133→  },
134→};
135→
136→export class ConfigManager extends EventEmitter {
137→  private config!: Config;
138→  private configPath: string;
139→
140→  constructor() {
141→    super();
142→    this.configPath =
143→      process.env.OPENACP_CONFIG_PATH || expandHome("~/.openacp/config.json");
144→  }
145→
146→  async load(): Promise<void> {
147→    // 1. Ensure directory exists
148→    const dir = path.dirname(this.configPath);
149→    fs.mkdirSync(dir, { recursive: true });
150→
151→    // 2. If config file doesn't exist, create default
152→    if (!fs.existsSync(this.configPath)) {
153→      fs.writeFileSync(
154→        this.configPath,
155→        JSON.stringify(DEFAULT_CONFIG, null, 2),
156→      );
157→      log.info({ configPath: this.configPath }, "Config created");
158→      log.info(
159→        "Please edit it with your Telegram bot token and chat ID, then restart.",
160→      );
161→      process.exit(1);
162→    }
163→
164→    // 3. Read and parse
165→    const raw = JSON.parse(fs.readFileSync(this.configPath, "utf-8"));
166→
167→    // 3.5. Auto-migrate config
168→    const { changed: configUpdated } = applyMigrations(raw);
169→    if (configUpdated) {
170→      fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2));
171→    }
172→
173→    // 4. Apply env var overrides
174→    this.applyEnvOverrides(raw);
175→
176→    // 5. Validate with Zod
177→    const result = ConfigSchema.safeParse(raw);
178→    if (!result.success) {
179→      log.error("Config validation failed");
180→      for (const issue of result.error.issues) {
181→        log.error(
182→          { path: issue.path.join("."), message: issue.message },
183→          "Validation error",
184→        );
185→      }
186→      process.exit(1);
187→    }
188→    this.config = result.data;
189→  }
190→
191→  get(): Config {
192→    return this.config;
193→  }
194→
195→  async save(updates: Record<string, unknown>, changePath?: string): Promise<void> {
196→    const oldConfig = this.config ? structuredClone(this.config) : undefined;
197→    // Read current file, merge updates, write back
198→    const raw = JSON.parse(fs.readFileSync(this.configPath, "utf-8"));
199→    this.deepMerge(raw, updates);
200→    fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2));
201→    // Re-validate and update in-memory config
202→    const result = ConfigSchema.safeParse(raw);
203→    if (result.success) {
204→      this.config = result.data;
205→    }
206→    // Emit change event if path provided
207→    if (changePath) {
208→      const { getConfigValue } = await import('./config-registry.js')
209→      const value = getConfigValue(this.config, changePath)
210→      const oldValue = oldConfig ? getConfigValue(oldConfig, changePath) : undefined
211→      this.emit('config:changed', { path: changePath, value, oldValue })
212→    }
213→  }
214→
215→  resolveWorkspace(input?: string): string {
216→    if (!input) {
217→      const resolved = expandHome(this.config.workspace.baseDir);
218→      fs.mkdirSync(resolved, { recursive: true });
219→      return resolved;
220→    }
221→    if (input.startsWith("/") || input.startsWith("~")) {
222→      const resolved = expandHome(input);
223→      fs.mkdirSync(resolved, { recursive: true });
224→      return resolved;
225→    }
226→    // Named workspace → lowercase, under baseDir
227→    const name = input.toLowerCase();
228→    const resolved = path.join(expandHome(this.config.workspace.baseDir), name);
229→    fs.mkdirSync(resolved, { recursive: true });
230→    return resolved;
231→  }
232→
233→  async exists(): Promise<boolean> {
234→    return fs.existsSync(this.configPath);
235→  }
236→
237→  getConfigPath(): string {
238→    return this.configPath;
239→  }
240→
241→  async writeNew(config: Config): Promise<void> {
242→    const dir = path.dirname(this.configPath);
243→    fs.mkdirSync(dir, { recursive: true });
244→    fs.writeFileSync(this.configPath, JSON.stringify(config, null, 2));
245→  }
246→
247→  private applyEnvOverrides(raw: Record<string, unknown>): void {
248→    const overrides: [string, string[]][] = [
249→      ["OPENACP_TELEGRAM_BOT_TOKEN", ["channels", "telegram", "botToken"]],
250→      ["OPENACP_TELEGRAM_CHAT_ID", ["channels", "telegram", "chatId"]],
251→      ["OPENACP_DEFAULT_AGENT", ["defaultAgent"]],
252→      ["OPENACP_RUN_MODE", ["runMode"]],
253→      ["OPENACP_API_PORT", ["api", "port"]],
254→    ];
255→    for (const [envVar, configPath] of overrides) {
256→      const value = process.env[envVar];
257→      if (value !== undefined) {
258→        let target = raw as Record<string, any>;
259→        for (let i = 0; i < configPath.length - 1; i++) {
260→          if (!target[configPath[i]]) target[configPath[i]] = {};
261→          target = target[configPath[i]];
262→        }
263→        const key = configPath[configPath.length - 1];
264→        // Convert numeric fields to number
265→        target[key] = (key === "chatId" || key === "port") ? Number(value) : value;
266→      }
267→    }
268→
269→    // Logging env var overrides
270→    if (process.env.OPENACP_LOG_LEVEL) {
271→      raw.logging = raw.logging || {};
272→      (raw.logging as Record<string, unknown>).level =
273→        process.env.OPENACP_LOG_LEVEL;
274→    }
275→    if (process.env.OPENACP_LOG_DIR) {
276→      raw.logging = raw.logging || {};
277→      (raw.logging as Record<string, unknown>).logDir =
278→        process.env.OPENACP_LOG_DIR;
279→    }
280→    if (process.env.OPENACP_DEBUG && !process.env.OPENACP_LOG_LEVEL) {
281→      raw.logging = raw.logging || {};
282→      (raw.logging as Record<string, unknown>).level = "debug";
283→    }
284→
285→    // Tunnel env var overrides
286→    if (process.env.OPENACP_TUNNEL_ENABLED) {
287→      raw.tunnel = raw.tunnel || {};
288→      (raw.tunnel as Record<string, unknown>).enabled =
289→        process.env.OPENACP_TUNNEL_ENABLED === "true";
290→    }
291→    if (process.env.OPENACP_TUNNEL_PORT) {
292→      raw.tunnel = raw.tunnel || {};
293→      (raw.tunnel as Record<string, unknown>).port = Number(
294→        process.env.OPENACP_TUNNEL_PORT,
295→      );
296→    }
297→    if (process.env.OPENACP_TUNNEL_PROVIDER) {
298→      raw.tunnel = raw.tunnel || {};
299→      (raw.tunnel as Record<string, unknown>).provider =
300→        process.env.OPENACP_TUNNEL_PROVIDER;
301→    }
302→  }
303→
304→  private deepMerge(
305→    target: Record<string, any>,
306→    source: Record<string, any>,
307→  ): void {
308→    for (const key of Object.keys(source)) {
309→      if (
310→        source[key] &&
311→        typeof source[key] === "object" &&
312→        !Array.isArray(source[key])
313→      ) {
314→        if (!target[key]) target[key] = {};
315→        this.deepMerge(target[key], source[key]);
316→      } else {
317→        target[key] = source[key];
318→      }
319→    }
320→  }
321→}
