 1→import { execSync } from 'node:child_process'
 2→import * as fs from 'node:fs'
 3→import * as path from 'node:path'
 4→import { createRequire } from 'node:module'
 5→import { PLUGINS_DIR } from './config.js'
 6→import { createChildLogger } from './log.js'
 7→const log = createChildLogger({ module: 'plugin-manager' })
 8→import type { ChannelAdapter } from './channel.js'
 9→
10→export interface AdapterFactory {
11→  name: string
12→  createAdapter(core: any, config: any): ChannelAdapter
13→}
14→
15→function ensurePluginsDir(): void {
16→  fs.mkdirSync(PLUGINS_DIR, { recursive: true })
17→  const pkgPath = path.join(PLUGINS_DIR, 'package.json')
18→  if (!fs.existsSync(pkgPath)) {
19→    fs.writeFileSync(pkgPath, JSON.stringify({ name: 'openacp-plugins', private: true, dependencies: {} }, null, 2))
20→  }
21→}
22→
23→export function installPlugin(packageName: string): void {
24→  ensurePluginsDir()
25→  log.info({ packageName }, 'Installing plugin')
26→  execSync(`npm install ${packageName} --prefix "${PLUGINS_DIR}"`, { stdio: 'inherit' })
27→  log.info({ packageName }, 'Plugin installed successfully')
28→}
29→
30→export function uninstallPlugin(packageName: string): void {
31→  ensurePluginsDir()
32→  log.info({ packageName }, 'Uninstalling plugin')
33→  execSync(`npm uninstall ${packageName} --prefix "${PLUGINS_DIR}"`, { stdio: 'inherit' })
34→  log.info({ packageName }, 'Plugin uninstalled')
35→}
36→
37→export function listPlugins(): Record<string, string> {
38→  const pkgPath = path.join(PLUGINS_DIR, 'package.json')
39→  if (!fs.existsSync(pkgPath)) return {}
40→  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'))
41→  return pkg.dependencies || {}
42→}
43→
44→export async function loadAdapterFactory(packageName: string): Promise<AdapterFactory | null> {
45→  try {
46→    const require = createRequire(path.join(PLUGINS_DIR, 'package.json'))
47→    const resolved = require.resolve(packageName)
48→    const mod = await import(resolved)
49→
50→    // Plugin must export `adapterFactory` or default export conforming to AdapterFactory
51→    const factory: AdapterFactory | undefined = mod.adapterFactory || mod.default
52→    if (!factory || typeof factory.createAdapter !== 'function') {
53→      log.error({ packageName }, 'Plugin does not export a valid AdapterFactory (needs .createAdapter())')
54→      return null
55→    }
56→    return factory
57→  } catch (err) {
58→    log.error({ packageName, err }, 'Failed to load plugin')
59→    log.error({ packageName }, 'Run: npx openacp install <packageName>')
60→    return null
61→  }
62→}
