 72→export class TelegramAdapter extends ChannelAdapter<OpenACPCore> {
 73→  private bot!: Bot;
 74→  private telegramConfig: TelegramChannelConfig;
 75→  private permissionHandler!: PermissionHandler;
 76→  private assistantSession: Session | null = null;
 77→  private assistantInitializing = false;
 78→  private notificationTopicId!: number;
 79→  private assistantTopicId!: number;
 80→  private sendQueue = new TelegramSendQueue(3000);
 81→
 82→  // Extracted managers
 83→  private toolTracker!: ToolCallTracker;
 84→  private draftManager!: DraftManager;
 85→  private skillManager!: SkillCommandManager;
 86→  private sessionTrackers: Map<string, ActivityTracker> = new Map();
 87→
 88→  private getOrCreateTracker(sessionId: string, threadId: number): ActivityTracker {
 89→    let tracker = this.sessionTrackers.get(sessionId);
 90→    if (!tracker) {
 91→      tracker = new ActivityTracker(
 92→        this.bot.api,
 93→        this.telegramConfig.chatId,
 94→        threadId,
 95→        this.sendQueue,
 96→      );
 97→      this.sessionTrackers.set(sessionId, tracker);
 98→    }
 99→    return tracker;
100→  }
101→
102→  constructor(core: OpenACPCore, config: TelegramChannelConfig) {
103→    super(core, config as never);
104→    this.telegramConfig = config;
105→  }
106→
107→  async start(): Promise<void> {
108→    this.bot = new Bot(this.telegramConfig.botToken, { client: { fetch: patchedFetch } });
109→
110→    // Initialize extracted managers
111→    this.toolTracker = new ToolCallTracker(this.bot, this.telegramConfig.chatId, this.sendQueue);
112→    this.draftManager = new DraftManager(this.bot, this.telegramConfig.chatId, this.sendQueue);
113→    this.skillManager = new SkillCommandManager(
114→      this.bot,
115→      this.telegramConfig.chatId,
116→      this.sendQueue,
117→      this.core.sessionManager,
118→    );
119→
120→    // Global error handler — prevent unhandled errors from crashing the bot
121→    this.bot.catch((err) => {
122→      const rootCause = err.error instanceof Error ? err.error : err;
123→      log.error({ err: rootCause }, "Telegram bot error");
124→    });
125→
126→    // Auto-retry on 429 (Too Many Requests)
127→    this.bot.api.config.use(async (prev, method, payload, signal) => {
128→      const maxRetries = 3;
129→      for (let attempt = 0; attempt <= maxRetries; attempt++) {
130→        const result = await prev(method, payload, signal);
131→        if (
132→          result.ok ||
133→          (result as { error_code?: number }).error_code !== 429 ||
134→          attempt === maxRetries
135→        ) {
136→          return result;
137→        }
138→        const retryAfter =
139→          ((result as { parameters?: { retry_after?: number } }).parameters
140→            ?.retry_after ?? 5) + 1;
141→        const rateLimitedMethods = ['sendMessage', 'editMessageText', 'editMessageReplyMarkup'];
142→        if (rateLimitedMethods.includes(method)) {
143→          this.sendQueue.onRateLimited();
144→        }
145→        log.warn(
146→          { method, retryAfter, attempt: attempt + 1 },
147→          "Rate limited by Telegram, retrying",
148→        );
149→        await new Promise((r) => setTimeout(r, retryAfter * 1000));
150→      }
151→      return prev(method, payload, signal);
152→    });
153→
154→    // Ensure allowed_updates includes callback_query on every poll
155→    this.bot.api.config.use((prev, method, payload, signal) => {
156→      if (method === "getUpdates") {
157→        const p = payload as never as Record<string, unknown>;
158→        p.allowed_updates = (p.allowed_updates as string[] | undefined) ?? [
159→          "message",
160→          "callback_query",
161→        ];
162→      }
163→      return prev(method, payload, signal);
164→    });
165→
166→    // Register static commands for Telegram autocomplete
167→    await this.bot.api.setMyCommands(STATIC_COMMANDS, {
168→      scope: { type: "chat", chat_id: this.telegramConfig.chatId },
169→    });
170→
171→    // Middleware: only accept updates from configured chatId
172→    this.bot.use((ctx, next) => {
173→      const chatId = ctx.chat?.id ?? ctx.callbackQuery?.message?.chat?.id;
174→      if (chatId !== this.telegramConfig.chatId) return;
175→      return next();
176→    });
177→
178→    // Ensure system topics exist
179→    const topics = await ensureTopics(
180→      this.bot,
181→      this.telegramConfig.chatId,
182→      this.telegramConfig,
183→      async (updates) => {
184→        await this.core.configManager.save({
185→          channels: { telegram: updates },
186→        });
187→      },
188→    );
189→    this.notificationTopicId = topics.notificationTopicId;
190→    this.assistantTopicId = topics.assistantTopicId;
191→
192→    // Setup permission handler
193→    this.permissionHandler = new PermissionHandler(
194→      this.bot,
195→      this.telegramConfig.chatId,
196→      (sessionId) =>
197→        this.core.sessionManager.getSession(sessionId),
198→      (notification) => this.sendNotification(notification),
199→    );
200→
201→    // Callback registration order matters!
202→    setupDangerousModeCallbacks(this.bot, this.core as OpenACPCore);
203→    setupActionCallbacks(
204→      this.bot,
205→      this.core as OpenACPCore,
206→      this.telegramConfig.chatId,
207→      () => this.assistantSession?.id,
208→    );
209→    setupIntegrateCallbacks(this.bot, this.core as OpenACPCore);
210→    setupMenuCallbacks(
211→      this.bot,
212→      this.core as OpenACPCore,
213→      this.telegramConfig.chatId,
214→      { notificationTopicId: this.notificationTopicId, assistantTopicId: this.assistantTopicId },
215→      () => {
216→        if (!this.assistantSession) return undefined;
217→        return {
218→          topicId: this.assistantTopicId,
219→          enqueuePrompt: (p: string) => this.assistantSession!.enqueuePrompt(p),
220→        };
221→      },
222→    );
223→    setupCommands(
224→      this.bot,
225→      this.core as OpenACPCore,
226→      this.telegramConfig.chatId,
227→      {
228→        topicId: this.assistantTopicId,
229→        getSession: () => this.assistantSession,
230→        respawn: async () => {
231→          if (this.assistantSession) {
232→            await this.assistantSession.destroy();
233→            this.assistantSession = null;
234→          }
235→          const { session, ready } = await spawnAssistant(
236→            this.core as OpenACPCore,
237→            this,
238→            this.assistantTopicId,
239→          );
240→          this.assistantSession = session;
241→          this.assistantInitializing = true;
242→          ready.then(() => { this.assistantInitializing = false; });
243→        },
244→      },
245→    );
246→    this.permissionHandler.setupCallbackHandler();
247→
248→    // /handoff command
249→    this.bot.command("handoff", async (ctx) => {
250→      const threadId = ctx.message?.message_thread_id;
251→      if (!threadId) return;
252→
253→      if (threadId === this.notificationTopicId || threadId === this.assistantTopicId) {
254→        await ctx.reply("This command only works in session topics.", {
255→          message_thread_id: threadId,
256→        });
257→        return;
258→      }
259→
260→      const session = this.core.sessionManager.getSessionByThread("telegram", String(threadId));
261→      const record = session ? undefined : this.core.sessionManager.getRecordByThread("telegram", String(threadId));
262→
263→      const agentName = session?.agentName ?? record?.agentName;
264→      const agentSessionId = session?.agentSessionId ?? record?.agentSessionId;
265→
266→      if (!agentName || !agentSessionId) {
267→        await ctx.reply("No session found for this topic.", {
268→          message_thread_id: threadId,
269→        });
270→        return;
271→      }
272→
273→      const { getAgentCapabilities } = await import("../../core/agent-registry.js");
274→      const caps = getAgentCapabilities(agentName);
275→
276→      if (!caps.supportsResume || !caps.resumeCommand) {
277→        await ctx.reply("This agent does not support session transfer.", {
278→          message_thread_id: threadId,
279→        });
280→        return;
281→      }
282→
283→      const command = caps.resumeCommand(agentSessionId);
284→
285→      await ctx.reply(
286→        `Run this in your terminal to continue the session:\n\n<code>${command}</code>`,
287→        {
288→          message_thread_id: threadId,
289→          parse_mode: "HTML",
290→        },
291→      );
292→    });
293→
294→    // Setup message routing
295→    this.setupRoutes();
296→
297→    // Start bot polling
298→    this.bot.start({
299→      allowed_updates: ["message", "callback_query"],
300→      onStart: () =>
