362→
363→  private setupRoutes(): void {
364→    this.bot.on("message:text", async (ctx) => {
365→      const threadId = ctx.message.message_thread_id;
366→
367→      // Check for pending workspace input from interactive /new flow
368→      if (await handlePendingWorkspaceInput(ctx, this.core, this.telegramConfig.chatId, this.assistantTopicId)) {
369→        return;
370→      }
371→
372→      // General topic or no thread → redirect to assistant
373→      if (!threadId) {
374→        const html = redirectToAssistant(
375→          this.telegramConfig.chatId,
376→          this.assistantTopicId,
377→        );
378→        await ctx.reply(html, { parse_mode: "HTML" });
379→        return;
380→      }
381→
382→      // Notification topic → ignore
383→      if (threadId === this.notificationTopicId) return;
384→
385→      // Assistant topic → forward to assistant session
386→      if (threadId === this.assistantTopicId) {
387→        if (!this.assistantSession) {
388→          await ctx.reply("⚠️ Assistant is not available yet. Please try again shortly.", { parse_mode: "HTML" });
389→          return;
390→        }
391→        await this.draftManager.finalize(this.assistantSession.id, this.assistantSession.id);
392→        ctx.replyWithChatAction("typing").catch(() => {});
393→        handleAssistantMessage(this.assistantSession, ctx.message.text).catch(
394→          (err) => log.error({ err }, "Assistant error"),
395→        );
396→        return;
397→      }
398→
399→      // Session topic → forward to core
400→      const sessionId = this.core.sessionManager.getSessionByThread("telegram", String(threadId))?.id;
401→      if (sessionId) await this.draftManager.finalize(sessionId, this.assistantSession?.id);
402→      if (sessionId) {
403→        const tracker = this.sessionTrackers.get(sessionId);
404→        if (tracker) await tracker.onNewPrompt();
405→      }
406→      ctx.replyWithChatAction("typing").catch(() => {});
407→      this.core
408→        .handleMessage({
409→          channelId: "telegram",
410→          threadId: String(threadId),
411→          userId: String(ctx.from.id),
412→          text: ctx.message.text,
413→        })
414→        .catch((err) => log.error({ err }, "handleMessage error"));
415→    });
416→  }
