  1→import type { Bot } from "grammy";
  2→import type { TelegramSendQueue } from "./send-queue.js";
  3→import { formatToolCall, formatToolUpdate } from "./formatting.js";
  4→import { createChildLogger } from "../../core/log.js";
  5→
  6→const log = createChildLogger({ module: "tool-call-tracker" });
  7→
  8→interface ToolCallState {
  9→  msgId: number;
 10→  name: string;
 11→  kind?: string;
 12→  viewerLinks?: { file?: string; diff?: string };
 13→  viewerFilePath?: string;
 14→  ready: Promise<void>;
 15→}
 16→
 17→interface ToolCallMeta {
 18→  id: string;
 19→  name: string;
 20→  kind?: string;
 21→  status?: string;
 22→  content?: unknown;
 23→  viewerLinks?: { file?: string; diff?: string };
 24→  viewerFilePath?: string;
 25→}
 26→
 27→export class ToolCallTracker {
 28→  private sessions: Map<string, Map<string, ToolCallState>> = new Map();
 29→
 30→  constructor(
 31→    private bot: Bot,
 32→    private chatId: number,
 33→    private sendQueue: TelegramSendQueue,
 34→  ) {}
 35→
 36→  async trackNewCall(
 37→    sessionId: string,
 38→    threadId: number,
 39→    meta: ToolCallMeta,
 40→  ): Promise<void> {
 41→    if (!this.sessions.has(sessionId)) {
 42→      this.sessions.set(sessionId, new Map());
 43→    }
 44→
 45→    let resolveReady!: () => void;
 46→    const ready = new Promise<void>((r) => {
 47→      resolveReady = r;
 48→    });
 49→
 50→    this.sessions.get(sessionId)!.set(meta.id, {
 51→      msgId: 0,
 52→      name: meta.name,
 53→      kind: meta.kind,
 54→      viewerLinks: meta.viewerLinks,
 55→      viewerFilePath: meta.viewerFilePath,
 56→      ready,
 57→    });
 58→
 59→    const msg = await this.sendQueue.enqueue(() =>
 60→      this.bot.api.sendMessage(
 61→        this.chatId,
 62→        formatToolCall(meta),
 63→        {
 64→          message_thread_id: threadId,
 65→          parse_mode: "HTML",
 66→          disable_notification: true,
 67→        },
 68→      ),
 69→    );
 70→
 71→    const toolEntry = this.sessions.get(sessionId)!.get(meta.id)!;
 72→    toolEntry.msgId = msg!.message_id;
 73→    resolveReady();
 74→  }
 75→
 76→  async updateCall(
 77→    sessionId: string,
 78→    meta: ToolCallMeta & { status: string },
 79→  ): Promise<void> {
 80→    const toolState = this.sessions.get(sessionId)?.get(meta.id);
 81→    if (!toolState) return;
 82→
 83→    // Accumulate state from intermediate updates
 84→    if (meta.viewerLinks) {
 85→      toolState.viewerLinks = meta.viewerLinks;
 86→      log.debug({ toolId: meta.id, viewerLinks: meta.viewerLinks }, "Accumulated viewerLinks");
 87→    }
 88→    if (meta.viewerFilePath) toolState.viewerFilePath = meta.viewerFilePath;
 89→    if (meta.name) toolState.name = meta.name;
 90→    if (meta.kind) toolState.kind = meta.kind;
 91→
 92→    // Only edit on terminal status — minimizes API calls to avoid rate limits
 93→    const isTerminal = meta.status === "completed" || meta.status === "failed";
 94→    if (!isTerminal) return;
 95→
 96→    await toolState.ready;
 97→
 98→    log.debug(
 99→      {
100→        toolId: meta.id,
101→        status: meta.status,
102→        hasViewerLinks: !!toolState.viewerLinks,
103→        viewerLinks: toolState.viewerLinks,
104→        name: toolState.name,
105→        msgId: toolState.msgId,
106→      },
107→      "Tool completed, preparing edit",
108→    );
109→
110→    const merged = {
111→      ...meta,
112→      name: toolState.name,
113→      kind: toolState.kind,
114→      viewerLinks: toolState.viewerLinks,
115→      viewerFilePath: toolState.viewerFilePath,
116→    };
117→    const formattedText = formatToolUpdate(merged);
118→
119→    try {
120→      await this.sendQueue.enqueue(() =>
121→        this.bot.api.editMessageText(
122→          this.chatId,
123→          toolState.msgId,
124→          formattedText,
125→          { parse_mode: "HTML" },
126→        ),
127→      );
128→    } catch (err) {
129→      log.warn(
130→        {
131→          err,
132→          msgId: toolState.msgId,
133→          textLen: formattedText.length,
134→          hasViewerLinks: !!merged.viewerLinks,
135→        },
136→        "Tool update edit failed",
137→      );
138→    }
139→  }
140→
141→  cleanup(sessionId: string): void {
142→    this.sessions.delete(sessionId);
143→  }
144→}
