 1→import type { Bot } from "grammy";
 2→import { MessageDraft } from "./streaming.js";
 3→import type { TelegramSendQueue } from "./send-queue.js";
 4→import {
 5→  detectAction,
 6→  storeAction,
 7→  buildActionKeyboard,
 8→} from "./action-detect.js";
 9→
10→export class DraftManager {
11→  private drafts: Map<string, MessageDraft> = new Map();
12→  private textBuffers: Map<string, string> = new Map();
13→
14→  constructor(
15→    private bot: Bot,
16→    private chatId: number,
17→    private sendQueue: TelegramSendQueue,
18→  ) {}
19→
20→  getOrCreate(sessionId: string, threadId: number): MessageDraft {
21→    let draft = this.drafts.get(sessionId);
22→    if (!draft) {
23→      draft = new MessageDraft(
24→        this.bot,
25→        this.chatId,
26→        threadId,
27→        this.sendQueue,
28→        sessionId,
29→      );
30→      this.drafts.set(sessionId, draft);
31→    }
32→    return draft;
33→  }
34→
35→  hasDraft(sessionId: string): boolean {
36→    return this.drafts.has(sessionId);
37→  }
38→
39→  appendText(sessionId: string, text: string): void {
40→    this.textBuffers.set(
41→      sessionId,
42→      (this.textBuffers.get(sessionId) ?? "") + text,
43→    );
44→  }
45→
46→  /**
47→   * Finalize the current draft and return the message ID.
48→   * Optionally detects actions in assistant responses.
49→   */
50→  async finalize(
51→    sessionId: string,
52→    assistantSessionId?: string,
53→  ): Promise<void> {
54→    const draft = this.drafts.get(sessionId);
55→    if (!draft) return;
56→
57→    // Delete BEFORE awaiting to prevent concurrent finalizeDraft() calls
58→    // from double-finalizing the same draft
59→    this.drafts.delete(sessionId);
60→    const finalMsgId = await draft.finalize();
61→
62→    // Detect actions in assistant responses and attach keyboard
63→    if (assistantSessionId && sessionId === assistantSessionId) {
64→      const fullText = this.textBuffers.get(sessionId);
65→      this.textBuffers.delete(sessionId);
66→      if (fullText && finalMsgId) {
67→        const detected = detectAction(fullText);
68→        if (detected) {
69→          const actionId = storeAction(detected);
70→          const keyboard = buildActionKeyboard(actionId, detected);
71→          try {
72→            await this.bot.api.editMessageReplyMarkup(
73→              this.chatId,
74→              finalMsgId,
75→              { reply_markup: keyboard },
76→            );
77→          } catch {
78→            // Best effort — keyboard attachment is non-critical
79→          }
80→        }
81→      }
82→    } else {
83→      this.textBuffers.delete(sessionId);
84→    }
85→  }
86→
87→  cleanup(sessionId: string): void {
88→    this.drafts.delete(sessionId);
89→    this.textBuffers.delete(sessionId);
90→  }
91→}
