 94→export function setupActionCallbacks(
 95→  bot: Bot,
 96→  core: OpenACPCore,
 97→  chatId: number,
 98→  getAssistantSessionId: () => string | undefined,
 99→): void {
100→  // IMPORTANT: dismiss handler MUST be registered BEFORE generic a: handler
101→  // because grammY routes to the first matching handler and /^a:/ also matches a:dismiss:
102→  bot.callbackQuery(/^a:dismiss:/, async (ctx) => {
103→    const actionId = ctx.callbackQuery.data.replace("a:dismiss:", "");
104→    removeAction(actionId);
105→    try {
106→      await ctx.editMessageReplyMarkup({
107→        reply_markup: { inline_keyboard: [] },
108→      });
109→    } catch {
110→      /* message may be old */
111→    }
112→    await ctx.answerCallbackQuery({ text: "Dismissed" });
113→  });
114→
115→  bot.callbackQuery(/^a:(?!dismiss)/, async (ctx) => {
116→    const actionId = ctx.callbackQuery.data.replace("a:", "");
117→    const action = getAction(actionId);
118→    if (!action) {
119→      await ctx.answerCallbackQuery({ text: "Action expired" });
120→      return;
121→    }
122→    removeAction(actionId);
123→
124→    try {
125→      if (action.action === "new_session") {
126→        // If both agent and workspace provided → create directly
127→        if (action.agent && action.workspace) {
128→          await ctx.answerCallbackQuery({ text: "⏳ Creating session..." });
129→          const { threadId, firstMsgId } = await executeNewSession(
130→            bot,
131→            core,
132→            chatId,
133→            action.agent,
134→            action.workspace,
135→          );
136→          const topicLink = `https://t.me/c/${String(chatId).replace("-100", "")}/${firstMsgId ?? threadId}`;
137→          const originalText = ctx.callbackQuery.message?.text ?? "";
138→          try {
139→            await ctx.editMessageText(
140→              originalText +
141→                `\n\n✅ Session created → <a href="${topicLink}">Go to topic</a>`,
142→              { parse_mode: "HTML" },
143→            );
144→          } catch {
145→            await ctx.editMessageReplyMarkup({
146→              reply_markup: { inline_keyboard: [] },
147→            });
148→          }
149→        } else {
150→          // Missing workspace → start interactive flow
151→          await ctx.answerCallbackQuery();
152→          try {
153→            await ctx.editMessageReplyMarkup({
154→              reply_markup: { inline_keyboard: [] },
155→            });
156→          } catch { /* best effort */ }
157→          await startInteractiveNewSession(ctx, core, chatId, action.agent);
158→        }
159→      } else if (action.action === "cancel_session") {
160→        const assistantId = getAssistantSessionId();
161→        const cancelled = await executeCancelSession(core, assistantId);
162→        if (cancelled) {
163→          await ctx.answerCallbackQuery({ text: "⛔ Session cancelled" });
164→          const originalText = ctx.callbackQuery.message?.text ?? "";
165→          try {
166→            await ctx.editMessageText(
167→              originalText +
168→                `\n\n⛔ Session "${cancelled.name ?? cancelled.id}" cancelled`,
169→              { parse_mode: "HTML" },
170→            );
171→          } catch {
172→            await ctx.editMessageReplyMarkup({
173→              reply_markup: { inline_keyboard: [] },
174→            });
175→          }
176→        } else {
177→          await ctx.answerCallbackQuery({
178→            text: "No active session",
179→          });
180→          try {
181→            await ctx.editMessageReplyMarkup({
182→              reply_markup: { inline_keyboard: [] },
183→            });
184→          } catch {
185→            /* best effort */
186→          }
187→        }
188→      }
189→    } catch {
190→      await ctx.answerCallbackQuery({ text: "❌ Error, try again later" });
191→      try {
192→        await ctx.editMessageReplyMarkup({
193→          reply_markup: { inline_keyboard: [] },
194→        });
195→      } catch {
196→        /* best effort */
197→      }
198→    }
199→  });
200→}
