 39→export function setupAllCallbacks(
 40→  bot: Bot,
 41→  core: OpenACPCore,
 42→  chatId: number,
 43→  systemTopicIds?: { notificationTopicId: number; assistantTopicId: number },
 44→  getAssistantSession?: () => { topicId: number; enqueuePrompt: (p: string) => Promise<void> } | undefined,
 45→): void {
 46→  // Register specific prefix handlers FIRST (grammY middleware order matters)
 47→  setupNewSessionCallbacks(bot, core, chatId);
 48→  setupSessionCallbacks(bot, core, chatId, systemTopicIds);
 49→
 50→  // Settings handlers — must be before broad m: handler
 51→  setupSettingsCallbacks(bot, core, getAssistantSession ?? (() => undefined))
 52→
 53→  // Doctor handlers — must be before broad m: handler
 54→  setupDoctorCallbacks(bot);
 55→
 56→  // Agent callbacks (install + pagination) — must be before broad m: handler
 57→  bot.callbackQuery(/^ag:/, (ctx) => handleAgentCallback(ctx, core));
