 80→      case "m:agents":
 81→        await handleAgents(ctx, core);
 82→        break;
 83→      case "m:help":
 84→        await handleHelp(ctx);
 85→        break;
 86→      case "m:restart":
 87→        await handleRestart(ctx, core);
 88→        break;
 89→      case "m:update":
 90→        await handleUpdate(ctx, core);
 91→        break;
 92→      case "m:integrate":
 93→        await handleIntegrate(ctx, core);
 94→        break;
 95→      case "m:topics":
 96→        await handleTopics(ctx, core);
 97→        break;
 98→      case "m:settings":
 99→        await handleSettings(ctx, core);
100→        break;
101→    }
102→  });
