 82→const TELEGRAM_MSG_LIMIT = 4096;
 83→
 84→/**
 85→ * Build plain-text skill command messages. Each command is on its own line
 86→ * wrapped in <code> for tap-to-copy. If the list exceeds Telegram's message
 87→ * limit, it is split into multiple messages (cut at line boundaries).
 88→ */
 89→export function buildSkillMessages(commands: AgentCommand[]): string[] {
 90→  const sorted = [...commands].sort((a, b) => a.name.localeCompare(b.name));
 91→  const header = "🛠 <b>Available Skills</b>\n";
 92→  const lines = sorted.map((c) => `<code>/${c.name}</code>`);
 93→
 94→  const messages: string[] = [];
 95→  let current = header;
 96→
 97→  for (const line of lines) {
 98→    const candidate = current + "\n" + line;
 99→    if (candidate.length > TELEGRAM_MSG_LIMIT) {
100→      messages.push(current);
101→      current = line;
102→    } else {
103→      current = candidate;
104→    }
105→  }
106→  if (current) messages.push(current);
107→  return messages;
108→}
