162→export async function createSessionDirect(
163→  ctx: Context,
164→  core: OpenACPCore,
165→  chatId: number,
166→  agentName: string,
167→  workspace: string,
168→): Promise<number | null> {
169→  log.info({ userId: ctx.from?.id, agentName, workspace }, "New session command (direct)");
170→
171→  let threadId: number | undefined;
172→  try {
173→    const topicName = `🔄 New Session`;
174→    threadId = await createSessionTopic(botFromCtx(ctx), chatId, topicName);
175→
176→    await ctx.api.sendMessage(chatId, `⏳ Setting up session, please wait...`, {
177→      message_thread_id: threadId,
178→      parse_mode: "HTML",
179→    });
180→
181→    const session = await core.handleNewSession("telegram", agentName, workspace);
182→    session.threadId = String(threadId);
183→
184→    await core.sessionManager.patchRecord(session.id, { platform: { topicId: threadId } });
185→
186→    const finalName = `🔄 ${session.agentName} — New Session`;
187→    try {
188→      await ctx.api.editForumTopic(chatId, threadId, { name: finalName });
189→    } catch { /* ignore rename failures */ }
190→
191→    await ctx.api.sendMessage(
192→      chatId,
193→      `✅ <b>Session started</b>\n` +
194→        `<b>Agent:</b> ${escapeHtml(session.agentName)}\n` +
195→        `<b>Workspace:</b> <code>${escapeHtml(session.workingDirectory)}</code>\n\n` +
196→        `This is your coding session — chat here to work with the agent.`,
197→      {
198→        message_thread_id: threadId,
199→        parse_mode: "HTML",
200→        reply_markup: buildDangerousModeKeyboard(session.id, false),
201→      },
202→    );
203→
204→    session.warmup().catch((err) => log.error({ err }, "Warm-up error"));
205→    return threadId ?? null;
206→  } catch (err) {
207→    log.error({ err }, "Session creation failed");
208→    if (threadId) {
209→      try { await ctx.api.deleteForumTopic(chatId, threadId); } catch { /* ignore */ }
210→    }
211→    const message = err instanceof Error ? err.message : (typeof err === 'object' ? JSON.stringify(err) : String(err));
212→    await ctx.reply(`❌ ${escapeHtml(message)}`, { parse_mode: "HTML" });
213→    return null;
214→  }
215→}
