316→export async function executeNewSession(
317→  bot: Bot,
318→  core: OpenACPCore,
319→  chatId: number,
320→  agentName?: string,
321→  workspace?: string,
322→): Promise<{ session: Session; threadId: number; firstMsgId: number }> {
323→  // Create topic with generic name first (same as original handleNew)
324→  const threadId = await createSessionTopic(bot, chatId, "🔄 New Session");
325→
326→  const setupMsg = await bot.api.sendMessage(chatId, "⏳ Setting up session, please wait...", {
327→    message_thread_id: threadId,
328→    parse_mode: "HTML",
329→  });
330→  const firstMsgId = setupMsg.message_id;
331→
332→  try {
333→    // core.handleNewSession() already wires events internally — do NOT call wireSessionEvents again
334→    const session = await core.handleNewSession(
335→      "telegram",
336→      agentName,
337→      workspace,
338→    );
339→    session.threadId = String(threadId);
340→
341→    await core.sessionManager.patchRecord(session.id, { platform: {
342→      topicId: threadId,
343→    } });
344→
345→    // Rename topic with agent name after session is created
346→    const finalName = `🔄 ${session.agentName} — New Session`;
347→    await renameSessionTopic(bot, chatId, threadId, finalName);
348→
349→    // Warm up model cache in background while user types
350→    session.warmup().catch((err) => log.error({ err }, "Warm-up error"));
351→
352→    return { session, threadId, firstMsgId };
353→  } catch (err) {
354→    // Clean up orphaned topic on failure
355→    try {
356→      await bot.api.deleteForumTopic(chatId, threadId);
357→    } catch {
358→      /* best effort */
359→    }
360→    throw err;
361→  }
362→}
