 10→export async function handleCancel(
 11→  ctx: Context,
 12→  core: OpenACPCore,
 13→  assistant?: CommandsAssistantContext,
 14→): Promise<void> {
 15→  const threadId = ctx.message?.message_thread_id;
 16→  if (!threadId) return;
 17→
 18→  // In assistant topic: forward to assistant for confirmation
 19→  if (assistant && threadId === assistant.topicId) {
 20→    const assistantSession = assistant.getSession();
 21→    if (assistantSession) {
 22→      await assistantSession.enqueuePrompt(
 23→        "User wants to cancel a session. Confirm which session to cancel.",
 24→      );
 25→      return;
 26→    }
 27→  }
 28→
 29→  const session = core.sessionManager.getSessionByThread(
 30→    "telegram",
 31→    String(threadId),
 32→  );
 33→  if (session) {
 34→    log.info({ sessionId: session.id }, "Cancel session command");
 35→    await session.abortPrompt();
 36→    await ctx.reply("⛔ Session cancelled.", { parse_mode: "HTML" });
 37→    return;
 38→  }
 39→
 40→  // Fallback: cancel from store when session not in memory (e.g. after restart)
 41→  const record = core.sessionManager.getRecordByThread("telegram", String(threadId));
 42→  if (record && record.status !== "cancelled" && record.status !== "error") {
 43→    log.info({ sessionId: record.sessionId }, "Cancel session command (from store)");
 44→    await core.sessionManager.cancelSession(record.sessionId);
 45→    await ctx.reply("⛔ Session cancelled.", { parse_mode: "HTML" });
 46→  }
 47→}
