 96→export async function handleTopics(ctx: Context, core: OpenACPCore): Promise<void> {
 97→  try {
 98→    const allRecords = core.sessionManager.listRecords();
 99→
100→    // Only show sessions that have a Telegram topic (skip headless/CLI-only)
101→    const records = allRecords.filter((r) => {
102→      const platform = r.platform as { topicId?: number };
103→      return !!platform?.topicId;
104→    });
105→
106→    const headlessCount = allRecords.length - records.length;
107→
108→    if (records.length === 0) {
109→      const extra = headlessCount > 0 ? ` (${headlessCount} headless hidden)` : "";
110→      await ctx.reply(`No sessions with topics found.${extra}`, { parse_mode: "HTML" });
111→      return;
112→    }
113→
114→    const statusEmoji: Record<string, string> = {
115→      active: "🟢",
116→      initializing: "🟡",
117→      finished: "✅",
118→      error: "❌",
119→      cancelled: "⛔",
120→    };
121→
122→    // Sort: active/initializing first, then by lastActiveAt desc
123→    const statusOrder: Record<string, number> = { active: 0, initializing: 1, error: 2, finished: 3, cancelled: 4 };
124→    records.sort((a, b) => (statusOrder[a.status] ?? 5) - (statusOrder[b.status] ?? 5));
125→
126→    const MAX_DISPLAY = 30;
127→    const displayed = records.slice(0, MAX_DISPLAY);
128→
129→    const lines = displayed.map((r) => {
130→      const emoji = statusEmoji[r.status] || "⚪";
131→      const name = r.name?.trim();
132→      const label = name ? escapeHtml(name) : `<i>${escapeHtml(r.agentName)} session</i>`;
133→      return `${emoji} ${label}  <code>[${r.status}]</code>`;
134→    });
135→
136→    const header = `<b>Sessions: ${records.length}</b>` +
137→      (headlessCount > 0 ? ` (${headlessCount} headless hidden)` : "");
138→    const truncated = records.length > MAX_DISPLAY ? `\n\n<i>...and ${records.length - MAX_DISPLAY} more</i>` : "";
139→
140→    // Count by status for cleanup buttons (include headless sessions)
141→    const finishedCount = allRecords.filter((r) => r.status === "finished").length;
142→    const errorCount = allRecords.filter((r) => r.status === "error" || r.status === "cancelled").length;
143→
144→    const keyboard = new InlineKeyboard();
145→    if (finishedCount > 0) {
146→      keyboard.text(`Cleanup finished (${finishedCount})`, "m:cleanup:finished").row();
147→    }
148→    if (errorCount > 0) {
149→      keyboard.text(`Cleanup errors (${errorCount})`, "m:cleanup:errors").row();
150→    }
151→    if (finishedCount + errorCount > 0) {
152→      keyboard.text(`Cleanup all non-active (${finishedCount + errorCount})`, "m:cleanup:all").row();
153→    }
154→    keyboard.text(`⚠️ Cleanup ALL (${allRecords.length})`, "m:cleanup:everything").row();
155→    keyboard.text("Refresh", "m:topics");
156→
157→    await ctx.reply(
158→      `${header}\n\n${lines.join("\n")}${truncated}`,
159→      { parse_mode: "HTML", reply_markup: keyboard },
160→    );
161→  } catch (err) {
162→    log.error({ err }, "handleTopics error");
163→    await ctx.reply("❌ Failed to list sessions.", { parse_mode: "HTML" }).catch(() => {});
164→  }
165→}
