167→export async function handleCleanup(ctx: Context, core: OpenACPCore, chatId: number, statuses: string[]): Promise<void> {
168→  const allRecords = core.sessionManager.listRecords();
169→  const cleanable = allRecords.filter((r) => statuses.includes(r.status));
170→
171→  if (cleanable.length === 0) {
172→    await ctx.reply("Nothing to clean up.", { parse_mode: "HTML" });
173→    return;
174→  }
175→
176→  let deleted = 0;
177→  let failed = 0;
178→
179→  for (const record of cleanable) {
180→    try {
181→      const topicId = (record.platform as { topicId?: number })?.topicId;
182→      if (topicId) {
183→        try {
184→          await ctx.api.deleteForumTopic(chatId, topicId);
185→        } catch (err) {
186→          log.warn({ err, sessionId: record.sessionId, topicId }, "Failed to delete forum topic during cleanup");
187→        }
188→      }
189→      await core.sessionManager.removeRecord(record.sessionId);
190→      deleted++;
191→    } catch (err) {
192→      log.error({ err, sessionId: record.sessionId }, "Failed to cleanup session");
193→      failed++;
194→    }
195→  }
196→
197→  await ctx.reply(
198→    `🗑 Cleaned up <b>${deleted}</b> sessions${failed > 0 ? ` (${failed} failed)` : ""}.`,
199→    { parse_mode: "HTML" },
200→  );
201→}
