203→export async function handleCleanupEverything(
204→  ctx: Context,
205→  core: OpenACPCore,
206→  chatId: number,
207→  systemTopicIds?: { notificationTopicId: number; assistantTopicId: number },
208→): Promise<void> {
209→  const allRecords = core.sessionManager.listRecords();
210→  const cleanable = allRecords.filter((r) => {
211→    const platform = r.platform as { topicId?: number };
212→    if (systemTopicIds && platform?.topicId && (platform.topicId === systemTopicIds.notificationTopicId || platform.topicId === systemTopicIds.assistantTopicId)) return false;
213→    return true;
214→  });
215→
216→  if (cleanable.length === 0) {
217→    await ctx.reply("Nothing to clean up.", { parse_mode: "HTML" });
218→    return;
219→  }
220→
221→  // Group by status for breakdown
222→  const statusCounts = new Map<string, number>();
223→  for (const r of cleanable) {
224→    statusCounts.set(r.status, (statusCounts.get(r.status) ?? 0) + 1);
225→  }
226→
227→  const statusEmoji: Record<string, string> = {
228→    active: "🟢", initializing: "🟡", finished: "✅", error: "❌", cancelled: "⛔",
229→  };
230→
231→  const breakdown = Array.from(statusCounts.entries())
232→    .map(([status, count]) => `${statusEmoji[status] ?? "⚪"} ${status}: ${count}`)
233→    .join("\n");
234→
235→  const activeCount = (statusCounts.get("active") ?? 0) + (statusCounts.get("initializing") ?? 0);
236→  const activeWarning = activeCount > 0
237→    ? `\n\n⚠️ <b>${activeCount} active session(s) will be cancelled and their agents stopped!</b>`
238→    : "";
239→
240→  const keyboard = new InlineKeyboard()
241→    .text("Yes, delete all", "m:cleanup:everything:confirm")
242→    .text("Cancel", "m:topics");
243→
244→  await ctx.reply(
245→    `<b>Delete ${cleanable.length} topics?</b>\n\n` +
246→    `This will:\n` +
247→    `• Delete all session topics from this group\n` +
248→    `• Cancel any running agent sessions\n` +
249→    `• Remove all session records\n\n` +
250→    `<b>Breakdown:</b>\n${breakdown}${activeWarning}\n\n` +
251→    `<i>Notifications and Assistant topics will NOT be deleted.</i>`,
252→    { parse_mode: "HTML", reply_markup: keyboard },
253→  );
254→}
255→
256→export async function handleCleanupEverythingConfirmed(
257→  ctx: Context,
258→  core: OpenACPCore,
259→  chatId: number,
260→  systemTopicIds?: { notificationTopicId: number; assistantTopicId: number },
261→): Promise<void> {
262→  const allRecords = core.sessionManager.listRecords();
263→  const cleanable = allRecords.filter((r) => {
264→    const platform = r.platform as { topicId?: number };
265→    if (systemTopicIds && platform?.topicId && (platform.topicId === systemTopicIds.notificationTopicId || platform.topicId === systemTopicIds.assistantTopicId)) return false;
266→    return true;
267→  });
268→
269→  if (cleanable.length === 0) {
270→    await ctx.reply("Nothing to clean up.", { parse_mode: "HTML" });
271→    return;
272→  }
273→
274→  let deleted = 0;
275→  let failed = 0;
276→
277→  for (const record of cleanable) {
278→    try {
279→      // Cancel active sessions first
280→      if (record.status === "active" || record.status === "initializing") {
281→        try {
282→          await core.sessionManager.cancelSession(record.sessionId);
283→        } catch (err) {
284→          log.warn({ err, sessionId: record.sessionId }, "Failed to cancel session during cleanup");
285→        }
286→      }
287→
288→      const topicId = (record.platform as { topicId?: number })?.topicId;
289→      if (topicId) {
290→        try {
291→          await ctx.api.deleteForumTopic(chatId, topicId);
292→        } catch (err) {
293→          log.warn({ err, sessionId: record.sessionId, topicId }, "Failed to delete forum topic during cleanup");
294→        }
295→      }
296→      await core.sessionManager.removeRecord(record.sessionId);
297→      deleted++;
298→    } catch (err) {
299→      log.error({ err, sessionId: record.sessionId }, "Failed to cleanup session");
300→      failed++;
301→    }
302→  }
303→
304→  await ctx.reply(
305→    `🗑 Cleaned up <b>${deleted}</b> sessions${failed > 0 ? ` (${failed} failed)` : ""}.`,
306→    { parse_mode: "HTML" },
307→  );
308→}
309→
310→export async function executeCancelSession(
311→  core: OpenACPCore,
312→  excludeSessionId?: string,
313→): Promise<Session | null> {
314→  const sessions = core.sessionManager
315→    .listSessions("telegram")
316→    .filter((s) => s.status === "active" && s.id !== excludeSessionId)
317→    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
318→
319→  const session = sessions[0];
320→  if (!session) return null;
321→
322→  await session.abortPrompt();
323→  return session;
324→}
325→
326→export function setupSessionCallbacks(
327→  bot: Bot,
328→  core: OpenACPCore,
329→  chatId: number,
330→  systemTopicIds?: { notificationTopicId: number; assistantTopicId: number },
331→): void {
332→  bot.callbackQuery(/^m:cleanup/, async (ctx) => {
333→    const data = ctx.callbackQuery.data;
334→    try {
335→      await ctx.answerCallbackQuery();
336→    } catch { /* expired */ }
337→
338→    switch (data) {
339→      case "m:cleanup:finished":
340→        await handleCleanup(ctx, core, chatId, ["finished"]);
341→        break;
342→      case "m:cleanup:errors":
343→        await handleCleanup(ctx, core, chatId, ["error", "cancelled"]);
344→        break;
345→      case "m:cleanup:all":
346→        await handleCleanup(ctx, core, chatId, ["finished", "error", "cancelled"]);
347→        break;
348→      case "m:cleanup:everything":
349→        await handleCleanupEverything(ctx, core, chatId, systemTopicIds);
350→        break;
351→      case "m:cleanup:everything:confirm":
352→        await handleCleanupEverythingConfirmed(ctx, core, chatId, systemTopicIds);
353→        break;
354→    }
355→  });
356→}
