  1→import type { Session } from "./session.js";
  2→import type { ChannelAdapter } from "./channel.js";
  3→import type { MessageTransformer } from "./message-transformer.js";
  4→import type { NotificationManager } from "./notification.js";
  5→import type { SessionManager } from "./session-manager.js";
  6→import type { AgentEvent, PermissionRequest, SessionStatus } from "./types.js";
  7→import { createChildLogger } from "./log.js";
  8→
  9→const log = createChildLogger({ module: "session-bridge" });
 10→
 11→export interface BridgeDeps {
 12→  messageTransformer: MessageTransformer;
 13→  notificationManager: NotificationManager;
 14→  sessionManager: SessionManager;
 15→}
 16→
 17→export class SessionBridge {
 18→  private connected = false;
 19→  private agentEventHandler?: (event: AgentEvent) => void;
 20→  private statusChangeHandler?: (from: SessionStatus, to: SessionStatus) => void;
 21→  private namedHandler?: (name: string) => void;
 22→
 23→  constructor(
 24→    private session: Session,
 25→    private adapter: ChannelAdapter,
 26→    private deps: BridgeDeps,
 27→  ) {}
 28→
 29→  connect(): void {
 30→    if (this.connected) return;
 31→    this.connected = true;
 32→
 33→    this.wireAgentToSession();
 34→    this.wireSessionToAdapter();
 35→    this.wirePermissions();
 36→    this.wireLifecycle();
 37→  }
 38→
 39→  disconnect(): void {
 40→    if (!this.connected) return;
 41→    this.connected = false;
 42→
 43→    if (this.agentEventHandler) {
 44→      this.session.off("agent_event", this.agentEventHandler);
 45→    }
 46→    if (this.statusChangeHandler) {
 47→      this.session.off("status_change", this.statusChangeHandler);
 48→    }
 49→    if (this.namedHandler) {
 50→      this.session.off("named", this.namedHandler);
 51→    }
 52→
 53→    // Reset agent callbacks to no-op
 54→    this.session.agentInstance.onSessionUpdate = () => {};
 55→    this.session.agentInstance.onPermissionRequest = async () => "";
 56→  }
 57→
 58→  private wireAgentToSession(): void {
 59→    this.session.agentInstance.onSessionUpdate = (event: AgentEvent) => {
 60→      this.session.emit("agent_event", event);
 61→    };
 62→  }
 63→
 64→  private wireSessionToAdapter(): void {
 65→    const session = this.session;
 66→    const ctx = {
 67→      get id() { return session.id; },
 68→      get workingDirectory() { return session.workingDirectory; },
 69→    };
 70→
 71→    this.agentEventHandler = (event: AgentEvent) => {
 72→      switch (event.type) {
 73→        case "text":
 74→        case "thought":
 75→        case "tool_call":
 76→        case "tool_update":
 77→        case "plan":
 78→        case "usage":
 79→          this.adapter.sendMessage(
 80→            this.session.id,
 81→            this.deps.messageTransformer.transform(event, ctx),
 82→          );
 83→          break;
 84→
 85→        case "session_end":
 86→          this.session.finish(event.reason);
 87→          this.adapter.cleanupSkillCommands(this.session.id);
 88→          this.adapter.sendMessage(
 89→            this.session.id,
 90→            this.deps.messageTransformer.transform(event),
 91→          );
 92→          this.deps.notificationManager.notify(this.session.channelId, {
 93→            sessionId: this.session.id,
 94→            sessionName: this.session.name,
 95→            type: "completed",
 96→            summary: `Session "${this.session.name || this.session.id}" completed`,
 97→          });
 98→          break;
 99→
100→        case "error":
101→          this.session.fail(event.message);
102→          this.adapter.cleanupSkillCommands(this.session.id);
103→          this.adapter.sendMessage(
104→            this.session.id,
105→            this.deps.messageTransformer.transform(event),
106→          );
107→          this.deps.notificationManager.notify(this.session.channelId, {
108→            sessionId: this.session.id,
109→            sessionName: this.session.name,
110→            type: "error",
111→            summary: event.message,
112→          });
113→          break;
114→
115→        case "commands_update":
116→          log.debug({ commands: event.commands }, "Commands available");
117→          this.adapter.sendSkillCommands(this.session.id, event.commands);
118→          break;
119→      }
120→    };
121→
122→    this.session.on("agent_event", this.agentEventHandler);
123→  }
124→
125→  private wirePermissions(): void {
126→    this.session.agentInstance.onPermissionRequest = async (
127→      request: PermissionRequest,
128→    ) => {
129→      this.session.emit("permission_request", request);
130→
131→      // Set pending BEFORE sending UI to avoid race condition
132→      const promise = this.session.permissionGate.setPending(request);
133→
134→      // Send permission UI to session topic
135→      await this.adapter.sendPermissionRequest(this.session.id, request);
136→
137→      // Wait for user response — adapter resolves this promise
138→      return promise;
139→    };
140→  }
141→
142→  private wireLifecycle(): void {
143→    // Persist status changes and auto-disconnect on terminal states
144→    this.statusChangeHandler = (from: SessionStatus, to: SessionStatus) => {
145→      this.deps.sessionManager.patchRecord(this.session.id, {
146→        status: to,
147→        lastActiveAt: new Date().toISOString(),
148→      });
149→
150→      // Auto-disconnect on terminal states
151→      if (to === "finished" || to === "cancelled") {
152→        // Disconnect on next tick so current event handlers can complete
153→        queueMicrotask(() => this.disconnect());
154→      }
155→    };
156→    this.session.on("status_change", this.statusChangeHandler);
157→
158→    // Persist and relay name changes
159→    this.namedHandler = (name: string) => {
160→      this.deps.sessionManager.patchRecord(this.session.id, { name });
161→      this.adapter.renameSessionThread(this.session.id, name);
162→    };
163→    this.session.on("named", this.namedHandler);
164→  }
165→}
