 15→export function setupDangerousModeCallbacks(bot: Bot, core: OpenACPCore): void {
 16→  bot.callbackQuery(/^d:/, async (ctx) => {
 17→    const sessionId = ctx.callbackQuery.data.slice(2);
 18→    const session = core.sessionManager.getSession(sessionId);
 19→
 20→    // Session live in memory — toggle directly
 21→    if (session) {
 22→      session.dangerousMode = !session.dangerousMode;
 23→      log.info({ sessionId, dangerousMode: session.dangerousMode }, "Dangerous mode toggled via button");
 24→      core.sessionManager.patchRecord(sessionId, { dangerousMode: session.dangerousMode }).catch(() => {});
 25→
 26→      const toastText = session.dangerousMode
 27→        ? "☠️ Dangerous mode enabled — permissions auto-approved"
 28→        : "🔐 Dangerous mode disabled — permissions shown normally";
 29→      try { await ctx.answerCallbackQuery({ text: toastText }); } catch { /* expired */ }
 30→
 31→      try {
 32→        await ctx.editMessageReplyMarkup({
 33→          reply_markup: buildDangerousModeKeyboard(sessionId, session.dangerousMode),
 34→        });
 35→      } catch { /* ignore */ }
 36→      return;
 37→    }
 38→
 39→    // Session not in memory (e.g. after restart) — toggle directly in store
 40→    const record = core.sessionManager.getSessionRecord(sessionId);
 41→    if (!record || record.status === "cancelled" || record.status === "error") {
 42→      try { await ctx.answerCallbackQuery({ text: "⚠️ Session not found or already ended." }); } catch { /* expired */ }
 43→      return;
 44→    }
 45→
 46→    const newDangerousMode = !(record.dangerousMode ?? false);
 47→    core.sessionManager.patchRecord(sessionId, { dangerousMode: newDangerousMode }).catch(() => {});
 48→    log.info({ sessionId, dangerousMode: newDangerousMode }, "Dangerous mode toggled via button (store-only, session not in memory)");
 49→
 50→    const toastText = newDangerousMode
 51→      ? "☠️ Dangerous mode enabled — permissions auto-approved"
 52→      : "🔐 Dangerous mode disabled — permissions shown normally";
 53→    try { await ctx.answerCallbackQuery({ text: toastText }); } catch { /* expired */ }
 54→
 55→    try {
 56→      await ctx.editMessageReplyMarkup({
 57→        reply_markup: buildDangerousModeKeyboard(sessionId, newDangerousMode),
 58→      });
 59→    } catch { /* ignore */ }
 60→  });
 61→}
