126→export async function handleUpdate(ctx: Context, core: OpenACPCore): Promise<void> {
127→  if (!core.requestRestart) {
128→    await ctx.reply("⚠️ Update is not available (no restart handler registered).", { parse_mode: "HTML" });
129→    return;
130→  }
131→
132→  const { getCurrentVersion, getLatestVersion, compareVersions, runUpdate } = await import("../../../cli/version.js");
133→  const current = getCurrentVersion();
134→  const statusMsg = await ctx.reply(`🔍 Checking for updates... (current: v${escapeHtml(current)})`, { parse_mode: "HTML" });
135→
136→  const latest = await getLatestVersion();
137→  if (!latest) {
138→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, "❌ Could not check for updates.", { parse_mode: "HTML" });
139→    return;
140→  }
141→
142→  if (compareVersions(current, latest) >= 0) {
143→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, `✅ Already up to date (v${escapeHtml(current)}).`, { parse_mode: "HTML" });
144→    return;
145→  }
146→
147→  await ctx.api.editMessageText(
148→    ctx.chat!.id,
149→    statusMsg.message_id,
150→    `⬇️ Updating v${escapeHtml(current)} → v${escapeHtml(latest)}...`,
151→    { parse_mode: "HTML" },
152→  );
153→
154→  const ok = await runUpdate();
155→  if (!ok) {
156→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, "❌ Update failed. Try manually: <code>npm install -g @openacp/cli@latest</code>", { parse_mode: "HTML" });
157→    return;
158→  }
159→
160→  await ctx.api.editMessageText(
161→    ctx.chat!.id,
162→    statusMsg.message_id,
163→    `✅ Updated to v${escapeHtml(latest)}. Restarting...`,
164→    { parse_mode: "HTML" },
165→  );
166→
167→  await new Promise((r) => setTimeout(r, 500));
168→  await core.requestRestart();
169→}
