171→export async function handleRestart(ctx: Context, core: OpenACPCore): Promise<void> {
172→  if (!core.requestRestart) {
173→    await ctx.reply("⚠️ Restart is not available (no restart handler registered).", { parse_mode: "HTML" });
174→    return;
