190→async function installAgentWithProgress(ctx: Context, core: OpenACPCore, nameOrId: string): Promise<void> {
191→  const catalog = core.agentCatalog;
192→  const msg = await ctx.reply(`⏳ Installing <b>${escapeHtml(nameOrId)}</b>...`, { parse_mode: "HTML" });
193→
194→  let lastEdit = 0;
195→  const EDIT_THROTTLE_MS = 1500;
196→
197→  const progress: InstallProgress = {
198→    onStart(_id, _name) { /* initial message already sent */ },
199→    async onStep(step) {
200→      const now = Date.now();
201→      if (now - lastEdit > EDIT_THROTTLE_MS) {
202→        lastEdit = now;
203→        try {
204→          await ctx.api.editMessageText(msg.chat.id, msg.message_id, `⏳ <b>${escapeHtml(nameOrId)}</b>: ${escapeHtml(step)}`, { parse_mode: "HTML" });
205→        } catch { /* rate limit or unchanged */ }
206→      }
207→    },
208→    async onDownloadProgress(percent) {
209→      const now = Date.now();
210→      if (now - lastEdit > EDIT_THROTTLE_MS) {
211→        lastEdit = now;
212→        try {
213→          const bar = buildProgressBar(percent);
214→          await ctx.api.editMessageText(msg.chat.id, msg.message_id, `⏳ <b>${escapeHtml(nameOrId)}</b>\nDownloading... ${bar} ${percent}%`, { parse_mode: "HTML" });
215→        } catch { /* rate limit */ }
216→      }
217→    },
218→    async onSuccess(name) {
219→      try {
220→        const keyboard = new InlineKeyboard().text(`🚀 Start session with ${name}`, `na:${nameOrId}`);
221→        await ctx.api.editMessageText(msg.chat.id, msg.message_id, `✅ <b>${escapeHtml(name)}</b> installed!`, { parse_mode: "HTML", reply_markup: keyboard });
222→      } catch { /* ignore */ }
223→    },
224→    async onError(error) {
225→      try {
226→        await ctx.api.editMessageText(msg.chat.id, msg.message_id, `❌ ${escapeHtml(error)}`, { parse_mode: "HTML" });
227→      } catch { /* ignore */ }
228→    },
229→  };
230→
231→  const result = await catalog.install(nameOrId, progress);
232→
233→  // Show setup steps as a follow-up message
234→  if (result.ok && result.setupSteps?.length) {
235→    let setupText = `📋 <b>Setup for ${escapeHtml(result.agentKey)}:</b>\n\n`;
236→    for (const step of result.setupSteps) {
237→      setupText += `→ ${escapeHtml(step)}\n`;
238→    }
239→    setupText += `\n<i>Run in terminal: openacp agents info ${escapeHtml(result.agentKey)}</i>`;
240→    try {
241→      await ctx.reply(setupText, { parse_mode: "HTML" });
242→    } catch { /* ignore */ }
243→  }
244→}
