246→function truncate(text: string, maxLen: number): string {
247→  if (text.length <= maxLen) return text;
248→  return text.slice(0, maxLen - 1) + "…";
249→}
250→
251→function buildProgressBar(percent: number): string {
252→  const filled = Math.round(percent / 10);
253→  const empty = 10 - filled;
254→  return "█".repeat(filled) + "░".repeat(empty);
255→}
