420→  async sendMessage(
421→    sessionId: string,
422→    content: OutgoingMessage,
423→  ): Promise<void> {
424→    // Suppress assistant messages during system prompt
425→    if (this.assistantInitializing && sessionId === this.assistantSession?.id) return;
426→
427→    const session = this.core.sessionManager.getSession(sessionId);
428→    if (!session) return;
429→    const threadId = Number(session.threadId);
430→    if (!threadId || isNaN(threadId)) {
431→      log.warn({ sessionId, threadId: session.threadId }, "Session has no valid threadId, skipping message");
432→      return;
433→    }
434→
435→    switch (content.type) {
436→      case "thought": {
437→        const tracker = this.getOrCreateTracker(sessionId, threadId);
438→        await tracker.onThought();
439→        break;
440→      }
441→
442→      case "text": {
443→        if (!this.draftManager.hasDraft(sessionId)) {
444→          const tracker = this.getOrCreateTracker(sessionId, threadId);
445→          await tracker.onTextStart();
446→        }
447→        const draft = this.draftManager.getOrCreate(sessionId, threadId);
448→        draft.append(content.text);
449→        this.draftManager.appendText(sessionId, content.text);
450→        break;
451→      }
452→
453→      case "tool_call": {
454→        const tracker = this.getOrCreateTracker(sessionId, threadId);
455→        await tracker.onToolCall();
456→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
457→        const meta = content.metadata as never as {
458→          id: string;
459→          name: string;
460→          kind?: string;
461→          status?: string;
462→          content?: unknown;
463→          viewerLinks?: { file?: string; diff?: string };
464→        };
465→        await this.toolTracker.trackNewCall(sessionId, threadId, {
466→          ...meta,
467→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
468→        });
469→        break;
470→      }
471→
472→      case "tool_update": {
473→        const meta = content.metadata as never as {
474→          id: string;
475→          name: string;
476→          kind?: string;
477→          status: string;
478→          content?: unknown;
479→          viewerLinks?: { file?: string; diff?: string };
480→        };
481→        await this.toolTracker.updateCall(sessionId, {
482→          ...meta,
483→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
484→        });
485→        break;
486→      }
487→
488→      case "plan": {
489→        const meta = content.metadata as never as {
490→          entries: Array<{ content: string; status: string; priority: string }>;
491→        };
492→        const tracker = this.getOrCreateTracker(sessionId, threadId);
493→        await tracker.onPlan(
494→          meta.entries.map(e => ({
495→            content: e.content,
496→            status: e.status as 'pending' | 'in_progress' | 'completed',
497→            priority: (e.priority ?? 'medium') as 'high' | 'medium' | 'low',
498→          })),
499→        );
500→        break;
501→      }
502→
503→      case "usage": {
504→        const meta = content.metadata as never as {
505→          tokensUsed?: number;
506→          contextSize?: number;
507→        };
508→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
509→        const tracker = this.getOrCreateTracker(sessionId, threadId);
510→        await tracker.sendUsage(meta);
511→
512→        // Notify the Notifications topic that a prompt has completed
513→        if (this.notificationTopicId && sessionId !== this.assistantSession?.id) {
514→          const sess = this.core.sessionManager.getSession(sessionId);
515→          const sessionName = sess?.name || 'Session';
516→          const chatIdStr = String(this.telegramConfig.chatId);
517→          const numericId = chatIdStr.startsWith('-100') ? chatIdStr.slice(4) : chatIdStr.replace('-', '');
518→          const usageMsgId = tracker.getUsageMsgId();
519→          const deepLink = `https://t.me/c/${numericId}/${usageMsgId ?? threadId}`;
520→          const text = `✅ <b>${escapeHtml(sessionName)}</b>\nTask completed.\n\n<a href="${deepLink}">→ Go to topic</a>`;
521→          this.sendQueue.enqueue(() =>
522→            this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
523→              message_thread_id: this.notificationTopicId,
524→              parse_mode: 'HTML',
525→              disable_notification: false,
526→            }),
527→          ).catch(() => {});
528→        }
529→        break;
530→      }
531→
532→      case "session_end": {
533→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
534→        this.draftManager.cleanup(sessionId);
535→        this.toolTracker.cleanup(sessionId);
536→        await this.skillManager.cleanup(sessionId);
537→        const tracker = this.sessionTrackers.get(sessionId);
538→        if (tracker) {
539→          await tracker.onComplete();
540→          tracker.destroy();
541→          this.sessionTrackers.delete(sessionId);
542→        } else {
543→          await this.sendQueue.enqueue(() =>
544→            this.bot.api.sendMessage(
545→              this.telegramConfig.chatId,
546→              `✅ <b>Done</b>`,
547→              {
548→                message_thread_id: threadId,
549→                parse_mode: "HTML",
550→                disable_notification: true,
551→              },
552→            ),
553→          );
554→        }
555→        break;
556→      }
557→
558→      case "error": {
559→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
560→        const tracker = this.sessionTrackers.get(sessionId);
561→        if (tracker) {
562→          tracker.destroy();
563→          this.sessionTrackers.delete(sessionId);
564→        }
565→        await this.sendQueue.enqueue(() =>
566→          this.bot.api.sendMessage(
567→            this.telegramConfig.chatId,
568→            `❌ <b>Error:</b> ${escapeHtml(content.text)}`,
569→            {
570→              message_thread_id: threadId,
571→              parse_mode: "HTML",
572→              disable_notification: true,
573→            },
574→          ),
575→        );
576→        break;
577→      }
578→    }
579→  }
