581→  async sendPermissionRequest(
582→    sessionId: string,
583→    request: PermissionRequest,
584→  ): Promise<void> {
585→    log.info({ sessionId, requestId: request.id }, "Permission request sent");
586→    const session = this.core.sessionManager.getSession(sessionId);
587→    if (!session) return;
588→
589→    // Auto-approve openacp CLI commands
590→    if (request.description.includes("openacp")) {
591→      const allowOption = request.options.find((o) => o.isAllow);
592→      if (allowOption && session.permissionGate.requestId === request.id) {
593→        log.info({ sessionId, requestId: request.id }, "Auto-approving openacp command");
594→        session.permissionGate.resolve(allowOption.id);
595→      }
596→      return;
597→    }
598→
599→    // Dangerous mode: auto-approve
600→    if (session.dangerousMode) {
601→      const allowOption = request.options.find((o) => o.isAllow);
602→      if (allowOption && session.permissionGate.requestId === request.id) {
603→        log.info({ sessionId, requestId: request.id, optionId: allowOption.id }, "Dangerous mode: auto-approving permission");
604→        session.permissionGate.resolve(allowOption.id);
605→      }
606→      return;
607→    }
608→
609→    await this.sendQueue.enqueue(() =>
610→      this.permissionHandler.sendPermissionRequest(session, request),
611→    );
612→  }
