614→  async sendNotification(notification: NotificationMessage): Promise<void> {
615→    if (notification.sessionId === this.assistantSession?.id) return;
616→
617→    log.info(
618→      { sessionId: notification.sessionId, type: notification.type },
619→      "Notification sent",
620→    );
621→    if (!this.notificationTopicId) return;
622→    const emoji: Record<string, string> = {
623→      completed: "✅",
624→      error: "❌",
625→      permission: "🔐",
626→      input_required: "💬",
627→    };
628→    let text = `${emoji[notification.type] || "ℹ️"} <b>${escapeHtml(notification.sessionName || "New session")}</b>\n`;
629→    text += escapeHtml(notification.summary);
630→
631→    const deepLink = notification.deepLink ?? (() => {
632→      const session = this.core.sessionManager.getSession(notification.sessionId);
633→      const threadId = session?.threadId;
634→      if (!threadId) return undefined;
635→      const chatIdStr = String(this.telegramConfig.chatId);
636→      const numericId = chatIdStr.startsWith("-100") ? chatIdStr.slice(4) : chatIdStr.replace("-", "");
637→      return `https://t.me/c/${numericId}/${threadId}`;
638→    })();
639→
640→    if (deepLink) {
641→      text += `\n\n<a href="${deepLink}">→ Go to topic</a>`;
642→    }
643→    await this.sendQueue.enqueue(() =>
644→      this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
645→        message_thread_id: this.notificationTopicId,
646→        parse_mode: "HTML",
647→        disable_notification: false,
648→      }),
649→    );
650→  }
