 92→export async function validateBotAdmin(
 93→  token: string,
 94→  chatId: number,
 95→): Promise<{ ok: true } | { ok: false; error: string }> {
 96→  try {
 97→    // Get bot's own user ID
 98→    const meRes = await fetch(`https://api.telegram.org/bot${token}/getMe`);
 99→    const meData = (await meRes.json()) as {
100→      ok: boolean;
101→      result?: { id: number };
102→    };
103→    if (!meData.ok || !meData.result) {
104→      return { ok: false, error: "Could not retrieve bot info" };
105→    }
106→
107→    const res = await fetch(
108→      `https://api.telegram.org/bot${token}/getChatMember`,
109→      {
110→        method: "POST",
111→        headers: { "Content-Type": "application/json" },
112→        body: JSON.stringify({ chat_id: chatId, user_id: meData.result.id }),
113→      },
114→    );
115→    const data = (await res.json()) as {
116→      ok: boolean;
117→      result?: { status: string };
118→      description?: string;
119→    };
120→    if (!data.ok || !data.result) {
121→      return {
122→        ok: false,
123→        error: data.description || "Could not check bot membership",
124→      };
125→    }
126→
127→    const { status } = data.result;
128→    if (status === "administrator" || status === "creator") {
129→      return { ok: true };
130→    }
131→    return {
132→      ok: false,
133→      error: `Bot is "${status}" in this group. It must be an admin. Please promote the bot to admin in group settings.`,
134→    };
135→  } catch (err) {
136→    return { ok: false, error: (err as Error).message };
137→  }
138→}
