153→async function detectChatId(token: string): Promise<number> {
154→  // Clear old updates
155→  let lastUpdateId = 0;
156→  try {
157→    const clearRes = await fetch(
158→      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
159→    );
160→    const clearData = (await clearRes.json()) as {
161→      ok: boolean;
162→      result?: Array<{ update_id: number }>;
163→    };
164→    if (clearData.ok && clearData.result?.length) {
165→      lastUpdateId = clearData.result[clearData.result.length - 1].update_id;
166→    }
167→  } catch {
168→    // ignore
169→  }
170→
171→  console.log("");
172→  console.log(`  ${c.bold}If you don't have a supergroup yet:${c.reset}`);
173→  console.log(dim("  1. Open Telegram → New Group → add your bot"));
174→  console.log(dim("  2. Group Settings → convert to Supergroup"));
175→  console.log(dim("  3. Enable Topics in group settings"));
176→  console.log("");
177→  console.log(`  ${c.bold}Then send "hi" in the group.${c.reset}`);
178→  console.log(
179→    dim(
180→      `  Listening... press ${c.reset}${c.yellow}m${c.reset}${c.dim} to enter ID manually`,
181→    ),
182→  );
183→  console.log("");
184→
185→  const MAX_ATTEMPTS = 120;
186→  const POLL_INTERVAL = 1000;
187→
188→  // Listen for 'm' keypress to switch to manual
189→  let cancelled = false;
190→  const onKeypress = (data: Buffer) => {
191→    const key = data.toString();
192→    if (key === "m" || key === "M") {
193→      cancelled = true;
194→    }
195→  };
196→  if (process.stdin.isTTY) {
197→    process.stdin.setRawMode(true);
198→    process.stdin.resume();
199→    process.stdin.on("data", onKeypress);
200→  }
201→
202→  const cleanup = () => {
203→    if (process.stdin.isTTY) {
204→      process.stdin.removeListener("data", onKeypress);
205→      process.stdin.setRawMode(false);
206→      process.stdin.pause();
207→    }
208→  };
209→
210→  try {
211→    for (let i = 0; i < MAX_ATTEMPTS; i++) {
212→      if (cancelled) {
213→        cleanup();
214→        return promptManualChatId();
215→      }
216→
217→      try {
218→        const offset = lastUpdateId ? lastUpdateId + 1 : 0;
219→        const res = await fetch(
220→          `https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=1`,
221→        );
222→        const data = (await res.json()) as {
223→          ok: boolean;
224→          result?: Array<{
225→            update_id: number;
226→            message?: {
227→              chat: { id: number; title?: string; type: string };
228→            };
229→            my_chat_member?: {
230→              chat: { id: number; title?: string; type: string };
231→            };
232→          }>;
233→        };
234→
235→        if (!data.ok || !data.result?.length) {
236→          await new Promise((r) => setTimeout(r, POLL_INTERVAL));
237→          continue;
238→        }
239→
240→        const groups = new Map<number, string>();
241→        for (const update of data.result) {
242→          lastUpdateId = update.update_id;
243→          const chat = update.message?.chat ?? update.my_chat_member?.chat;
244→          if (chat && (chat.type === "supergroup" || chat.type === "group")) {
245→            groups.set(chat.id, chat.title ?? String(chat.id));
246→          }
247→        }
248→
249→        if (groups.size === 1) {
250→          const [id, title] = [...groups.entries()][0];
251→          console.log(
252→            ok(`Group detected: ${c.bold}${title}${c.reset}${c.green} (${id})`),
253→          );
254→          cleanup();
255→          return id;
256→        }
257→
258→        if (groups.size > 1) {
259→          cleanup();
260→          const choices = [...groups.entries()].map(([id, title]) => ({
261→            name: `${title} (${id})`,
262→            value: id,
263→          }));
264→          return select({
265→            message: "Multiple groups found. Pick one:",
266→            choices,
267→          });
268→        }
269→      } catch {
270→        // Network error, retry
271→      }
272→      await new Promise((r) => setTimeout(r, POLL_INTERVAL));
273→    }
274→
275→    console.log(warn("Timed out waiting for messages."));
276→    cleanup();
277→    return promptManualChatId();
278→  } catch (err) {
279→    cleanup();
280→    throw err;
281→  }
282→}
