286→const KNOWN_AGENTS: Array<{ name: string; commands: string[] }> = [
287→  // claude-agent-acp is bundled as a dependency — no detection needed, but
288→  // kept here so detectAgents() still returns it for display purposes.
289→  { name: "claude", commands: ["claude-agent-acp"] },
290→  { name: "codex", commands: ["codex"] },
291→];
