293→export async function detectAgents(): Promise<
294→  Array<{ name: string; command: string }>
295→> {
296→  const found: Array<{ name: string; command: string }> = [];
297→  for (const agent of KNOWN_AGENTS) {
298→    // Find all available commands for this agent (PATH + node_modules/.bin)
299→    const available: string[] = [];
300→    for (const cmd of agent.commands) {
301→      if (commandExists(cmd)) {
302→        available.push(cmd);
303→      }
304→    }
305→    if (available.length > 0) {
306→      // Prefer claude-agent-acp over claude/claude-code (priority order)
307→      found.push({ name: agent.name, command: available[0] });
308→    }
309→  }
310→  return found;
311→}
