  1→import type { Bot } from "grammy";
  2→import type { TelegramSendQueue } from "./send-queue.js";
  3→import type { AgentCommand } from "../../core/types.js";
  4→import type { SessionManager } from "../../core/session-manager.js";
  5→import type { TelegramPlatformData } from "../../core/types.js";
  6→import { buildSkillMessages } from "./commands/index.js";
  7→import { createChildLogger } from "../../core/log.js";
  8→
  9→const log = createChildLogger({ module: "skill-commands" });
 10→
 11→export class SkillCommandManager {
 12→  private messages: Map<string, number> = new Map(); // sessionId → pinned msgId
 13→
 14→  constructor(
 15→    private bot: Bot,
 16→    private chatId: number,
 17→    private sendQueue: TelegramSendQueue,
 18→    private sessionManager: SessionManager,
 19→  ) {}
 20→
 21→  async send(
 22→    sessionId: string,
 23→    threadId: number,
 24→    commands: AgentCommand[],
 25→  ): Promise<void> {
 26→    // Restore skillMsgIds from persisted platform data if not in memory
 27→    if (!this.messages.has(sessionId)) {
 28→      const record = this.sessionManager.getSessionRecord(sessionId);
 29→      const platform = record?.platform as TelegramPlatformData | undefined;
 30→      if (platform?.skillMsgId) {
 31→        this.messages.set(sessionId, platform.skillMsgId);
 32→      }
 33→    }
 34→
 35→    // Empty commands → remove pinned message
 36→    if (commands.length === 0) {
 37→      await this.cleanup(sessionId);
 38→      return;
 39→    }
 40→
 41→    const messages = buildSkillMessages(commands);
 42→    const existingMsgId = this.messages.get(sessionId);
 43→
 44→    if (existingMsgId) {
 45→      try {
 46→        await this.bot.api.editMessageText(
 47→          this.chatId,
 48→          existingMsgId,
 49→          messages[0],
 50→          { parse_mode: "HTML" },
 51→        );
 52→        return;
 53→      } catch (err: unknown) {
 54→        const msg = err instanceof Error ? err.message : "";
 55→        if (msg.includes("message is not modified")) return;
 56→        try {
 57→          await this.bot.api.deleteMessage(this.chatId, existingMsgId);
 58→        } catch { /* already gone */ }
 59→        this.messages.delete(sessionId);
 60→      }
 61→    }
 62→
 63→    // Send new messages and pin the first one
 64→    try {
 65→      let firstMsgId: number | undefined;
 66→      for (const text of messages) {
 67→        const msg = await this.sendQueue.enqueue(() =>
 68→          this.bot.api.sendMessage(this.chatId, text, {
 69→            message_thread_id: threadId,
 70→            parse_mode: "HTML",
 71→            disable_notification: true,
 72→          }),
 73→        );
 74→        if (!firstMsgId) firstMsgId = msg!.message_id;
 75→      }
 76→
 77→      this.messages.set(sessionId, firstMsgId!);
 78→
 79→      // Persist skillMsgId so it survives restarts
 80→      const record = this.sessionManager.getSessionRecord(sessionId);
 81→      if (record) {
 82→        await this.sessionManager.patchRecord(sessionId, {
 83→          platform: { ...record.platform, skillMsgId: firstMsgId },
 84→        });
 85→      }
 86→
 87→      await this.bot.api.pinChatMessage(this.chatId, firstMsgId!, {
 88→        disable_notification: true,
 89→      });
 90→    } catch (err) {
 91→      log.error({ err, sessionId }, "Failed to send skill commands");
 92→    }
 93→  }
 94→
 95→  async cleanup(sessionId: string): Promise<void> {
 96→    const msgId = this.messages.get(sessionId);
 97→    if (!msgId) return;
 98→
 99→    try {
100→      await this.bot.api.editMessageText(
101→        this.chatId,
102→        msgId,
103→        "🛠 <i>Session ended</i>",
104→        { parse_mode: "HTML" },
105→      );
106→      await this.bot.api.unpinChatMessage(this.chatId, msgId);
107→    } catch { /* message may already be deleted */ }
108→
109→    this.messages.delete(sessionId);
110→
111→    // Clear persisted skillMsgId
112→    const record = this.sessionManager.getSessionRecord(sessionId);
113→    if (record) {
114→      const { skillMsgId: _removed, ...rest } = record.platform as unknown as TelegramPlatformData;
115→      await this.sessionManager.patchRecord(sessionId, { platform: rest });
116→    }
117→  }
118→}
