  1→import type { DoctorCheck, CheckResult } from "../types.js";
  2→
  3→const BOT_TOKEN_REGEX = /^\d+:[A-Za-z0-9_-]{35,}$/;
  4→
  5→export const telegramCheck: DoctorCheck = {
  6→  name: "Telegram",
  7→  order: 3,
  8→  async run(ctx) {
  9→    const results: CheckResult[] = [];
 10→
 11→    if (!ctx.config) {
 12→      results.push({ status: "fail", message: "Cannot check Telegram — config not loaded" });
 13→      return results;
 14→    }
 15→
 16→    const tgConfig = ctx.config.channels.telegram as Record<string, unknown> | undefined;
 17→    if (!tgConfig || !tgConfig.enabled) {
 18→      results.push({ status: "pass", message: "Telegram not enabled (skipped)" });
 19→      return results;
 20→    }
 21→
 22→    const botToken = tgConfig.botToken as string | undefined;
 23→    const chatId = tgConfig.chatId as number | undefined;
 24→
 25→    if (!botToken || !BOT_TOKEN_REGEX.test(botToken)) {
 26→      results.push({ status: "fail", message: "Bot token format invalid" });
 27→      return results;
 28→    }
 29→    results.push({ status: "pass", message: "Bot token format valid" });
 30→
 31→    let botId: number | undefined;
 32→    try {
 33→      const res = await fetch(`https://api.telegram.org/bot${botToken}/getMe`);
 34→      const data = (await res.json()) as { ok: boolean; result?: { id: number; username: string }; description?: string };
 35→      if (data.ok && data.result) {
 36→        botId = data.result.id;
 37→        results.push({ status: "pass", message: `Bot token valid (@${data.result.username})` });
 38→      } else {
 39→        results.push({ status: "fail", message: `Bot token rejected: ${data.description || "unknown error"}` });
 40→        return results;
 41→      }
 42→    } catch (err) {
 43→      results.push({ status: "fail", message: `Cannot reach Telegram API: ${err instanceof Error ? err.message : String(err)}` });
 44→      return results;
 45→    }
 46→
 47→    if (!chatId || chatId === 0) {
 48→      results.push({ status: "fail", message: "Chat ID not configured" });
 49→      return results;
 50→    }
 51→
 52→    try {
 53→      const res = await fetch(`https://api.telegram.org/bot${botToken}/getChat`, {
 54→        method: "POST",
 55→        headers: { "Content-Type": "application/json" },
 56→        body: JSON.stringify({ chat_id: chatId }),
 57→      });
 58→      const data = (await res.json()) as {
 59→        ok: boolean;
 60→        result?: { type: string; is_forum?: boolean; title: string };
 61→        description?: string;
 62→      };
 63→      if (!data.ok || !data.result) {
 64→        results.push({ status: "fail", message: `Chat ID invalid: ${data.description || "unknown error"}` });
 65→        return results;
 66→      }
 67→      if (data.result.type !== "supergroup") {
 68→        results.push({ status: "fail", message: `Chat is "${data.result.type}", must be a supergroup` });
 69→        return results;
 70→      }
 71→      if (!data.result.is_forum) {
 72→        results.push({ status: "warn", message: "Chat does not have topics enabled" });
 73→      } else {
 74→        results.push({ status: "pass", message: `Chat is supergroup with topics ("${data.result.title}")` });
 75→      }
 76→    } catch (err) {
 77→      results.push({ status: "fail", message: `Cannot validate chat: ${err instanceof Error ? err.message : String(err)}` });
 78→      return results;
 79→    }
 80→
 81→    try {
 82→      const res = await fetch(`https://api.telegram.org/bot${botToken}/getChatMember`, {
 83→        method: "POST",
 84→        headers: { "Content-Type": "application/json" },
 85→        body: JSON.stringify({ chat_id: chatId, user_id: botId }),
 86→      });
 87→      const data = (await res.json()) as { ok: boolean; result?: { status: string }; description?: string };
 88→      if (!data.ok || !data.result) {
 89→        results.push({ status: "fail", message: `Cannot check bot membership: ${data.description || "unknown"}` });
 90→      } else if (data.result.status === "administrator" || data.result.status === "creator") {
 91→        results.push({ status: "pass", message: "Bot is admin in group" });
 92→      } else {
 93→        results.push({
 94→          status: "fail",
 95→          message: `Bot is "${data.result.status}" — must be admin. Promote bot in group settings.`,
 96→        });
 97→      }
 98→    } catch (err) {
 99→      results.push({ status: "fail", message: `Admin check failed: ${err instanceof Error ? err.message : String(err)}` });
100→    }
101→
102→    return results;
103→  },
104→};
