 1→export type QueueItemType = 'text' | 'other'
 2→
 3→interface QueueItem<T = unknown> {
 4→  fn: () => Promise<T>
 5→  type: QueueItemType
 6→  key?: string
 7→  resolve: (value: T | undefined) => void
 8→  reject: (err: unknown) => void
 9→}
10→
11→export class TelegramSendQueue {
12→  private items: QueueItem[] = []
13→  private processing = false
14→  private lastExec = 0
15→  private minInterval: number
16→
17→  constructor(minInterval = 3000) {
18→    this.minInterval = minInterval
19→  }
20→
21→  enqueue<T>(
22→    fn: () => Promise<T>,
23→    opts?: { type?: QueueItemType; key?: string },
24→  ): Promise<T | undefined> {
25→    const type = opts?.type ?? 'other'
26→    const key = opts?.key
27→
28→    return new Promise<T | undefined>((resolve, reject) => {
29→      if (type === 'text' && key) {
30→        const idx = this.items.findIndex(
31→          (item) => item.type === 'text' && item.key === key,
32→        )
33→        if (idx !== -1) {
34→          this.items[idx].resolve(undefined)
35→          this.items[idx] = { fn, type, key, resolve, reject } as QueueItem
36→          this.scheduleProcess()
37→          return
38→        }
39→      }
40→
41→      this.items.push({ fn, type, key, resolve, reject } as QueueItem)
42→      this.scheduleProcess()
43→    })
44→  }
45→
46→  onRateLimited(): void {
47→    const remaining: QueueItem[] = []
48→    for (const item of this.items) {
49→      if (item.type === 'text') {
50→        item.resolve(undefined)
51→      } else {
52→        remaining.push(item)
53→      }
54→    }
55→    this.items = remaining
56→  }
57→
58→  private scheduleProcess(): void {
59→    if (this.processing) return
60→    if (this.items.length === 0) return
61→
62→    const elapsed = Date.now() - this.lastExec
63→    const delay = Math.max(0, this.minInterval - elapsed)
64→
65→    this.processing = true
66→    setTimeout(() => void this.processNext(), delay)
67→  }
68→
69→  private async processNext(): Promise<void> {
70→    const item = this.items.shift()
71→    if (!item) {
72→      this.processing = false
73→      return
74→    }
75→
76→    try {
77→      const result = await item.fn()
78→      item.resolve(result)
79→    } catch (err) {
80→      item.reject(err)
81→    } finally {
82→      this.lastExec = Date.now()
83→      this.processing = false
84→      this.scheduleProcess()
85→    }
86→  }
87→}
