 12→
 13→// Command patterns: /new [agent] [workspace], /cancel
 14→// Agent and workspace are ASCII-only tokens (no Unicode letters) to avoid matching non-ASCII words
 15→const CMD_NEW_RE =
 16→  /\/new(?:\s+([^\s\u0080-\uFFFF]+)(?:\s+([^\s\u0080-\uFFFF]+))?)?/;
 17→const CMD_CANCEL_RE = /\/cancel\b/;
 18→
 19→// Keyword patterns (compound phrases only to avoid false positives)
 20→const KW_NEW_RE = /(?:create|new)\s+session/i;
 21→const KW_CANCEL_RE = /(?:cancel|stop)\s+session/i;
 22→
 23→export function detectAction(text: string): DetectedAction | null {
 24→  if (!text) return null;
 25→
 26→  // Priority 1: command pattern
 27→  const cancelCmd = CMD_CANCEL_RE.exec(text);
 28→  if (cancelCmd) return { action: "cancel_session" };
 29→
 30→  const newCmd = CMD_NEW_RE.exec(text);
 31→  if (newCmd) {
 32→    return {
 33→      action: "new_session",
 34→      agent: newCmd[1] || undefined,
 35→      workspace: newCmd[2] || undefined,
 36→    };
 37→  }
 38→
 39→  // Priority 2: keyword matching
 40→  if (KW_CANCEL_RE.test(text)) return { action: "cancel_session" };
 41→  if (KW_NEW_RE.test(text))
 42→    return { action: "new_session", agent: undefined, workspace: undefined };
 43→
 44→  return null;
 45→}
 46→
 47→// --- Callback map for action buttons ---
 48→
 49→const ACTION_TTL_MS = 5 * 60 * 1000; // 5 minutes
 50→const actionMap: Map<string, { action: DetectedAction; createdAt: number }> =
 51→  new Map();
 52→
 53→export function storeAction(action: DetectedAction): string {
 54→  const id = nanoid(10);
 55→  actionMap.set(id, { action, createdAt: Date.now() });
 56→  // Cleanup expired entries
 57→  for (const [key, entry] of actionMap) {
 58→    if (Date.now() - entry.createdAt > ACTION_TTL_MS) {
 59→      actionMap.delete(key);
 60→    }
 61→  }
 62→  return id;
 63→}
 64→
 65→export function getAction(id: string): DetectedAction | undefined {
 66→  const entry = actionMap.get(id);
 67→  if (!entry) return undefined;
 68→  if (Date.now() - entry.createdAt > ACTION_TTL_MS) {
 69→    actionMap.delete(id);
 70→    return undefined;
 71→  }
 72→  return entry.action;
 73→}
 74→
 75→export function removeAction(id: string): void {
 76→  actionMap.delete(id);
 77→}
 78→
 79→export function buildActionKeyboard(
 80→  actionId: string,
 81→  action: DetectedAction,
 82→): InlineKeyboard {
 83→  const keyboard = new InlineKeyboard();
 84→  if (action.action === "new_session") {
 85→    keyboard.text("✅ Create session", `a:${actionId}`);
 86→    keyboard.text("❌ Cancel", `a:dismiss:${actionId}`);
 87→  } else {
 88→    keyboard.text("⛔ Cancel session", `a:${actionId}`);
 89→    keyboard.text("❌ No", `a:dismiss:${actionId}`);
 90→  }
 91→  return keyboard;
 92→}
 93→
 94→export function setupActionCallbacks(
 95→  bot: Bot,
 96→  core: OpenACPCore,
 97→  chatId: number,
 98→  getAssistantSessionId: () => string | undefined,
 99→): void {
100→  // IMPORTANT: dismiss handler MUST be registered BEFORE generic a: handler
101→  // because grammY routes to the first matching handler and /^a:/ also matches a:dismiss:
102→  bot.callbackQuery(/^a:dismiss:/, async (ctx) => {
103→    const actionId = ctx.callbackQuery.data.replace("a:dismiss:", "");
104→    removeAction(actionId);
105→    try {
106→      await ctx.editMessageReplyMarkup({
107→        reply_markup: { inline_keyboard: [] },
108→      });
109→    } catch {
110→      /* message may be old */
111→    }
112→    await ctx.answerCallbackQuery({ text: "Dismissed" });
113→  });
114→
115→  bot.callbackQuery(/^a:(?!dismiss)/, async (ctx) => {
116→    const actionId = ctx.callbackQuery.data.replace("a:", "");
117→    const action = getAction(actionId);
118→    if (!action) {
119→      await ctx.answerCallbackQuery({ text: "Action expired" });
120→      return;
121→    }
122→    removeAction(actionId);
123→
124→    try {
125→      if (action.action === "new_session") {
126→        // If both agent and workspace provided → create directly
127→        if (action.agent && action.workspace) {
128→          await ctx.answerCallbackQuery({ text: "⏳ Creating session..." });
129→          const { threadId, firstMsgId } = await executeNewSession(
130→            bot,
131→            core,
132→            chatId,
133→            action.agent,
134→            action.workspace,
135→          );
136→          const topicLink = `https://t.me/c/${String(chatId).replace("-100", "")}/${firstMsgId ?? threadId}`;
137→          const originalText = ctx.callbackQuery.message?.text ?? "";
138→          try {
139→            await ctx.editMessageText(
140→              originalText +
141→                `\n\n✅ Session created → <a href="${topicLink}">Go to topic</a>`,
142→              { parse_mode: "HTML" },
143→            );
144→          } catch {
145→            await ctx.editMessageReplyMarkup({
146→              reply_markup: { inline_keyboard: [] },
147→            });
148→          }
149→        } else {
150→          // Missing workspace → start interactive flow
151→          await ctx.answerCallbackQuery();
152→          try {
153→            await ctx.editMessageReplyMarkup({
154→              reply_markup: { inline_keyboard: [] },
155→            });
156→          } catch { /* best effort */ }
157→          await startInteractiveNewSession(ctx, core, chatId, action.agent);
158→        }
159→      } else if (action.action === "cancel_session") {
160→        const assistantId = getAssistantSessionId();
161→        const cancelled = await executeCancelSession(core, assistantId);
162→        if (cancelled) {
163→          await ctx.answerCallbackQuery({ text: "⛔ Session cancelled" });
164→          const originalText = ctx.callbackQuery.message?.text ?? "";
165→          try {
166→            await ctx.editMessageText(
167→              originalText +
168→                `\n\n⛔ Session "${cancelled.name ?? cancelled.id}" cancelled`,
169→              { parse_mode: "HTML" },
170→            );
171→          } catch {
172→            await ctx.editMessageReplyMarkup({
173→              reply_markup: { inline_keyboard: [] },
174→            });
175→          }
176→        } else {
177→          await ctx.answerCallbackQuery({
178→            text: "No active session",
179→          });
180→          try {
181→            await ctx.editMessageReplyMarkup({
182→              reply_markup: { inline_keyboard: [] },
183→            });
184→          } catch {
185→            /* best effort */
186→          }
187→        }
188→      }
189→    } catch {
190→      await ctx.answerCallbackQuery({ text: "❌ Error, try again later" });
191→      try {
192→        await ctx.editMessageReplyMarkup({
193→          reply_markup: { inline_keyboard: [] },
194→        });
195→      } catch {
196→        /* best effort */
197→      }
198→    }
199→  });
200→}
